                <div className="bg-brand-orange flex size-4 items-center justify-center rounded text-[8px] font-bold text-white">
                  B
                </div>
                {NAV_ITEMS[page].label}
              </span>
            </div>

            {/* Nội dung trang — kích thước thật, scroll dọc khi cao hơn màn */}
