function PieGrowBar({ pct, color }: { pct: number; color: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useGSAP(() => {
    if (!ref.current) return;
    gsap.fromTo(
      ref.current,
      { width: 0 },
      { width: `${pct}%`, duration: 0.7, ease: "power2.out" },
    );
  }, []);
  return (
    <div
      ref={ref}
      className={`h-full rounded-full ${color}`}
      style={{ width: 0 }}
    />
  );
}

