import * as React from "react";
import { Navigate, Outlet, useLocation } from "react-router-dom";
import { useAuthStore } from "@/store/authStore";
import { useWorkspaceStore } from "@/store/workspaceStore";
import { workspaceService } from "@/services/workspaceService";
import { userService } from "@/services/userService";
import { canAccess } from "@/routes/access";

export function AuthGuard() {
  const location = useLocation();
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated);
  const user = useAuthStore((s) => s.user);
  const systemRole = useAuthStore((s) => s.systemRole);
  const setSystemRole = useAuthStore((s) => s.setSystemRole);
  const memberRole = useWorkspaceStore((s) => s.currentMemberRole);
  const setCurrentMemberRole = useWorkspaceStore((s) => s.setCurrentMemberRole);

  const accessToken = useAuthStore((s) => s.accessToken);
  const isDevSession = accessToken?.startsWith("dev-token-") ?? false;

  const [roleLoaded, setRoleLoaded] = React.useState(false);

  React.useEffect(() => {
    if (!isAuthenticated || !user) return;
    if (isDevSession) {
      setRoleLoaded(true);
      return;
    }
    setRoleLoaded(false);
    Promise.all([
      userService
        .getProfile()
        .then(({ data }) =>
          setSystemRole(data.data.role === "ADMIN" ? "ADMIN" : "USER"),
        )
        .catch(() => setSystemRole(null)),
      workspaceService
        .list()
        .then(({ data }) => {
          const ws = data.data[0];
          if (!ws) return setCurrentMemberRole(null);
          return workspaceService
            .listMembers(ws.id)
            .then(({ data: membersRes }) => {
              const me = membersRes.data.find((m) => m.userId === user.id);
              setCurrentMemberRole(me?.role ?? null);
            });
        })
        .catch(() => setCurrentMemberRole(null)),
    ]).finally(() => setRoleLoaded(true));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isAuthenticated, user?.id]);

  if (!isAuthenticated) {
    return <Navigate to="/login" replace state={{ from: location }} />;
  }

  if (!roleLoaded) {
    return null;
  }

  if (!canAccess(location.pathname, systemRole, memberRole)) {
    return <Navigate to="/dashboard" replace />;
  }

  return <Outlet />;
}

export default AuthGuard;

import * as React from "react";
import { Outlet, NavLink, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useAuthStore } from "@/store/authStore";
import { useWorkspaceStore } from "@/store/workspaceStore";
import { useAgencyStore } from "@/store/agencyStore";
import { useClientProfileStore } from "@/store/clientProfileStore";
import { workspaceService } from "@/services/workspaceService";
import { userService } from "@/services/userService";
import { canAccess } from "@/routes/access";
import { Sidebar } from "./Sidebar";
import { Navbar } from "./Navbar";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  LayoutDashboard,
  FolderOpen,
  FileEdit,
  CalendarDays,
  Users,
  BarChart3,
} from "lucide-react";
import type { Workspace } from "@/types/workspace";

const MOBILE_TABS = [
  { to: "/dashboard", icon: LayoutDashboard, labelKey: "nav.dashboard" },
  { to: "/analytics", icon: BarChart3, labelKey: "nav.analytics" },
  { to: "/editor", icon: FileEdit, labelKey: "nav.editor" },
  { to: "/calendar", icon: CalendarDays, labelKey: "nav.calendar" },
  { to: "/workspace", icon: FolderOpen, labelKey: "nav.workspace" },
  { to: "/portal", icon: Users, labelKey: "nav.portal" },
];

export function Layout() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { user } = useAuthStore();
  const systemRole = useAuthStore((s) => s.systemRole);
  const setSystemRole = useAuthStore((s) => s.setSystemRole);

  const workspaces = useWorkspaceStore((s) => s.workspaceList);
  const currentAgencyId = useAgencyStore((s) => s.currentAgencyId);
  const setCurrentAgencyId = useAgencyStore((s) => s.setCurrentAgencyId);
  const agencyList = useAgencyStore((s) => s.agencyList);
  const fetchAgencies = useAgencyStore((s) => s.fetchAgencies);
  const agencyWorkspaces = React.useMemo(
    () =>
      currentAgencyId
        ? workspaces.filter((ws) => ws.agencyId === currentAgencyId)
        : [],
    [workspaces, currentAgencyId],
  );
  const currentWorkspace = useWorkspaceStore((s) => s.currentWorkspace);
  const setCurrentWorkspace = useWorkspaceStore((s) => s.setCurrentWorkspace);
  const fetchWorkspaces = useWorkspaceStore((s) => s.fetchWorkspaces);
  const memberRole = useWorkspaceStore((s) => s.currentMemberRole);
  const setCurrentMemberRole = useWorkspaceStore((s) => s.setCurrentMemberRole);
  const fetchMyClientProfile = useClientProfileStore((s) => s.fetchMyProfile);
  const resetClientProfile = useClientProfileStore((s) => s.reset);
  const accessToken = useAuthStore((s) => s.accessToken);
  const isDevSession = accessToken?.startsWith("dev-token-") ?? false;

  React.useEffect(() => {
    if (isDevSession) return;
    fetchWorkspaces();
    fetchAgencies();
  }, [fetchWorkspaces, fetchAgencies, isDevSession]);

  React.useEffect(() => {
    if (!user || isDevSession) return;
    userService
      .getProfile()
      .then(({ data }) => {
        const role = data.data.role;
        setSystemRole(role === "ADMIN" ? "ADMIN" : "USER");
      })
      .catch(() => setSystemRole(null));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]);

  const activeWorkspace: Workspace | null = React.useMemo(() => {
    if (agencyWorkspaces.length === 0) return null;
    return (
      agencyWorkspaces.find((ws) => ws.id === currentWorkspace?.id) ??
      agencyWorkspaces[0]
    );
  }, [agencyWorkspaces, currentWorkspace]);

  React.useEffect(() => {
    if (activeWorkspace && activeWorkspace.id !== currentWorkspace?.id) {
      setCurrentWorkspace(activeWorkspace);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeWorkspace]);

  React.useEffect(() => {
    if (!activeWorkspace || !user || isDevSession) return;
    workspaceService
      .listMembers(activeWorkspace.id)
      .then(({ data }) => {
        const me = data.data.find((m) => m.userId === user.id);
        setCurrentMemberRole(me?.role ?? null);
      })
      .catch(() => setCurrentMemberRole(null));
  }, [activeWorkspace, user]);

  // CLIENT chỉ có 1 ClientProfile mỗi agency — tự fetch/hiển thị đúng hồ sơ
  // của agency đang active, không cần màn hình chọn riêng.
  React.useEffect(() => {
    if (memberRole !== "CLIENT" || !currentAgencyId) {
      resetClientProfile();
      return;
    }
    fetchMyClientProfile(currentAgencyId);
  }, [memberRole, currentAgencyId, fetchMyClientProfile, resetClientProfile]);

  const currentRole = memberRole;

  // Sidebar collapse state loaded from localStorage
  const [collapsed, setCollapsed] = React.useState<boolean>(() => {
    const saved = localStorage.getItem("brandhub_sidebar_collapsed");
    return saved === "true";
  });

  const [mobileOpen, setMobileOpen] = React.useState(false);

  const toggleCollapsed = () => {
    setCollapsed((prev) => {
      const next = !prev;
      localStorage.setItem("brandhub_sidebar_collapsed", String(next));
      return next;
    });
  };

  // Auto-collapse sidebar at window width < 1280px and desktop mode >= 768px
  React.useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1280 && window.innerWidth >= 768) {
        setCollapsed(true);
      } else if (window.innerWidth >= 1280) {
        const saved = localStorage.getItem("brandhub_sidebar_collapsed");
        setCollapsed(saved === "true");
      }
    };
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // Filter mobile tabs based on role
  const filteredMobileTabs = MOBILE_TABS.filter((tab) => {
    if (
      !activeWorkspace &&
      tab.to !== "/dashboard" &&
      tab.to !== "/workspace"
    ) {
      return false;
    }
    return canAccess(tab.to, systemRole, memberRole);
  });

  const handleSwitchWorkspace = (agencyIdArg: string, workspaceId: string) => {
    const ws = workspaces.find((w) => w.id === workspaceId);
    if (!ws) return;
    setCurrentAgencyId(agencyIdArg);
    setCurrentWorkspace(ws);
    navigate(`/workspaces/${workspaceId}/settings`);
  };

  const handleSwitchAgency = (agencyIdArg: string) => {
    setCurrentAgencyId(agencyIdArg);
    if (currentWorkspace?.agencyId !== agencyIdArg) {
      setCurrentWorkspace(null);
    }
    navigate(`/agency/${agencyIdArg}`);
  };

  return (
    <div className="bg-background text-foreground flex h-screen w-screen overflow-hidden font-sans">
      {/* ── SIDEBAR (DESKTOP >= 768px) ── */}
      <aside className="hidden h-full shrink-0 md:block">
        <Sidebar
          collapsed={collapsed}
          role={currentRole}
          systemRole={systemRole}
          workspaces={agencyWorkspaces}
          activeWorkspace={activeWorkspace}
          onSwitchWorkspace={handleSwitchWorkspace}
          hasAgency={!!currentAgencyId}
          agencyList={agencyList}
          allWorkspaces={workspaces}
          currentAgencyId={currentAgencyId}
          onSwitchAgency={handleSwitchAgency}
        />
      </aside>

      {/* ── MAIN CONTENT CONTAINER ── */}
      <div className="relative flex min-w-0 flex-1 flex-col overflow-hidden">
        <Navbar
          collapsed={collapsed}
          toggleCollapsed={toggleCollapsed}
          onMobileMenuOpen={() => setMobileOpen(true)}
          memberRole={memberRole}
          workspaces={workspaces}
          agencies={agencyList}
        />

        {/* Dynamic Mobile Sheet Drawer */}
        <Sheet open={mobileOpen} onOpenChange={setMobileOpen}>
          <SheetContent side="left" className="w-[240px] border-0 p-0">
            <SheetHeader className="sr-only">
              <SheetTitle>{t("nav.navigationMenu")}</SheetTitle>
            </SheetHeader>
            <Sidebar
              collapsed={false}
              role={currentRole}
              systemRole={systemRole}
              workspaces={agencyWorkspaces}
              activeWorkspace={activeWorkspace}
              onSwitchWorkspace={handleSwitchWorkspace}
              onMobileItemClick={() => setMobileOpen(false)}
              hasAgency={!!currentAgencyId}
              agencyList={agencyList}
              allWorkspaces={workspaces}
              currentAgencyId={currentAgencyId}
              onSwitchAgency={handleSwitchAgency}
            />
          </SheetContent>
        </Sheet>

        {/* Page Content Outlet */}
        <main className="bg-background flex-1 overflow-y-auto pb-16 md:pb-0">
          <Outlet />
        </main>
      </div>

      {/* ── BOTTOM TAB BAR (MOBILE ONLY <= 768px) ── */}
      <div
        className="border-border pb-safe fixed right-0 bottom-0 left-0 z-40 flex h-16 items-center justify-around border-t md:hidden"
        style={{
          background: "hsl(var(--card, 0 0% 100%))",
          borderColor: "hsl(var(--border, 240 5.9% 90%))",
        }}
      >
        {filteredMobileTabs.slice(0, 5).map(({ to, icon: Icon, labelKey }) => {
          return (
            <NavLink
              key={to}
              to={to}
              end={to === "/"}
              className={({ isActive }) =>
                `text-3xs flex w-12 cursor-pointer flex-col items-center justify-center gap-1 py-1.5 transition-colors ${
                  isActive
                    ? "text-brand-orange font-semibold"
                    : "text-muted-foreground hover:text-foreground"
                }`
              }
            >
              <Icon className="size-5 shrink-0" />
              <span className="max-w-[55px] truncate">{t(labelKey)}</span>
            </NavLink>
          );
        })}
      </div>
    </div>
  );
}

export default Layout;

import * as React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  AtSign,
  Bell,
  CheckCircle,
  ChevronDown,
  Clock,
  Globe,
  Info,
  LogOut,
  Menu,
  Moon,
  PanelLeftClose,
  PanelLeftOpen,
  Settings,
  Shield,
  Sun,
  XCircle,
} from "lucide-react";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";
import { useAuthStore } from "@/store/authStore";
import { authService } from "@/services/authService";
import { useTheme } from "@/components/theme-provider";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { MemberRole, Workspace } from "@/types/workspace";
import type { Agency } from "@/types/agency";
import type { AppNotification, NotificationType } from "@/types/notification";
import {
  getNotifications,
  markAllAsRead,
  markAsRead,
} from "@/services/mock/mockNotificationService";

const NOTIFICATION_ICONS: Record<NotificationType, React.ElementType> = {
  APPROVAL_REQUEST: Clock,
  PUBLISH_SUCCESS: CheckCircle,
  PUBLISH_FAILED: XCircle,
  MENTION: AtSign,
  SYSTEM: Info,
};

const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const NAV_KEY_MAP: Record<string, string> = {
  dashboard: "nav.dashboard",
  workspace: "nav.workspace",
  workspaces: "nav.workspace",
  agency: "nav.agency",
  portal: "nav.portal",
  editor: "nav.editor",
  calendar: "nav.calendar",
  analytics: "nav.analytics",
  admin: "nav.admin",
  settings: "nav.settings",
  members: "workspace.members.title",
  invitations: "nav.invitations",
  clients: "nav.clients",
  requests: "nav.requests",
  templates: "nav.templates",
  "hashtag-groups": "nav.hashtagGroups",
  library: "nav.library",
  "social-accounts": "nav.socialAccounts",
  publish: "nav.publish",
  subscription: "nav.subscription",
  plans: "subscription.plans.title",
  checkout: "subscription.checkout.title",
  invoices: "subscription.invoices.title",
  "ai-studio": "nav.aiStudio",
  ambassadors: "aiStudio.ambassadors.title",
  "knowledge-base": "aiStudio.knowledgeBase.title",
  trends: "aiStudio.trends.title",
  reports: "nav.reports",
  create: "nav.sections.create",
  "notification-settings": "nav.notificationSettings",
  security: "nav.security",
  profile: "nav.profile",
  "client-profile": "nav.clientProfile",
  video: "aiStudio.video.title",
  "change-password": "nav.changePassword",
};

export interface NavbarProps {
  collapsed: boolean;
  toggleCollapsed: () => void;
  onMobileMenuOpen: () => void;
  memberRole: MemberRole | null;
  workspaces: Workspace[];
  agencies: Agency[];
}

export function Navbar({
  collapsed,
  toggleCollapsed,
  onMobileMenuOpen,
  memberRole,
  workspaces,
  agencies,
}: NavbarProps) {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, clearAuth } = useAuthStore();

  const username = user?.name || user?.email?.split("@")[0] || "User";

  const { theme, setTheme } = useTheme();
  const { i18n, t } = useTranslation();

  const [notifications, setNotifications] = React.useState<AppNotification[]>(
    [],
  );
  const unreadCount = notifications.filter((n) => !n.isRead).length;

  React.useEffect(() => {
    let cancelled = false;
    getNotifications()
      .then((data) => {
        if (!cancelled) setNotifications(data);
      })
      .catch((err) => console.error("Failed to load notifications:", err));
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleNotificationClick(n: AppNotification) {
    if (!n.isRead) {
      setNotifications((prev) =>
        prev.map((item) =>
          item.id === n.id ? { ...item, isRead: true } : item,
        ),
      );
      await markAsRead(n.id);
    }
    if (n.linkTo) navigate(n.linkTo);
  }

  async function handleMarkAllRead() {
    setNotifications((prev) => prev.map((item) => ({ ...item, isRead: true })));
    await markAllAsRead();
  }

  const getBreadcrumbs = () => {
    const segments = location.pathname.split("/").filter(Boolean);
    if (segments.length === 0)
      return [{ label: t("nav.dashboard"), path: "/" }];

    const crumbs: { label: string; path: string }[] = [];
    segments.forEach((seg, idx) => {
      const path = "/" + segments.slice(0, idx + 1).join("/");
      if (UUID_REGEX.test(seg)) {
        // UUID: xác định đây là agency hay workspace dựa vào segment gốc
        // ("agency" hoặc "workspaces") thay vì chỉ tìm trong workspaces —
        // trước đây agency id không map được tên nên bị bỏ luôn khỏi breadcrumb.
        const root = segments[0];
        const entity =
          root === "agency"
            ? agencies.find((a) => a.id === seg)
            : workspaces.find((ws) => ws.id === seg);
        crumbs.push({ label: entity?.name ?? seg, path });
        return;
      }
      const navKey = NAV_KEY_MAP[seg];
      const label = navKey
        ? t(navKey)
        : seg.charAt(0).toUpperCase() + seg.slice(1);
      crumbs.push({ label, path });
    });
    return crumbs;
  };

  const handleLogout = () => {
    // FR 3.2.8: blacklist token server-side (BR-14). Best-effort — clear
    // local state regardless of API outcome (token may already be expired).
    authService.logout().catch(() => {});
    clearAuth();
    navigate("/login");
  };

  const toggleLanguage = () => {
    const nextLang = i18n.language === "vi" ? "en" : "vi";
    i18n.changeLanguage(nextLang);
  };

  const breadcrumbs = getBreadcrumbs();
  const roleLabel = memberRole ? t(`workspace.roles.${memberRole}`) : null;

  return (
    <header
      className="bg-card border-border flex h-14 w-full items-center justify-between border-b px-4 transition-all"
      style={{ fontFamily: "var(--font-sans)" }}
    >
      {/* Left: Mobile Menu & Sidebar Toggle & Breadcrumbs */}
      <div className="flex items-center gap-3">
        <Button
          variant="ghost"
          size="icon"
          className="size-8 md:hidden"
          onClick={onMobileMenuOpen}
          title={t("nav.openMenu")}
        >
          <Menu className="size-4" />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          className="hidden size-8 md:flex"
          onClick={toggleCollapsed}
          title={collapsed ? t("nav.expandSidebar") : t("nav.collapseSidebar")}
        >
          {collapsed ? (
            <PanelLeftOpen className="size-4" />
          ) : (
            <PanelLeftClose className="size-4" />
          )}
        </Button>

        <nav className="text-muted-foreground hidden items-center gap-1.5 text-xs sm:flex">
          {breadcrumbs.map((b, idx) => {
            const isLast = idx === breadcrumbs.length - 1;
            return (
              <React.Fragment key={b.path}>
                {idx > 0 && <span className="text-muted-foreground/40">/</span>}
                <span
                  className={cn(
                    "transition-colors",
                    isLast
                      ? "text-foreground font-semibold"
                      : "hover:text-foreground cursor-pointer",
                  )}
                  onClick={() => !isLast && navigate(b.path)}
                >
                  {b.label}
                </span>
              </React.Fragment>
            );
          })}
        </nav>
      </div>

      {/* Right: Real Role Badge (Read-only), Language, Theme, Notifications & User Dropdown */}
      <div className="flex items-center gap-2">
        {/* Real Member Role Badge — only shown once inside a workspace */}
        {roleLabel && (
          <div
            className="flex h-8 items-center gap-1.5 rounded-md border border-dashed px-2.5 text-xs font-semibold select-none"
            style={{
              borderColor: "hsl(var(--brand-orange, 15 88% 55%))",
              color: "hsl(var(--brand-orange, 15 88% 55%))",
              background: "hsl(var(--brand-orange-soft, 15 100% 96%))",
            }}
            title={t("nav.realRoleTitle")}
          >
            <Shield className="size-3.5 shrink-0" />
            <span className="hidden sm:inline">
              {t("nav.roleLabel", { role: roleLabel })}
            </span>
            <span className="sm:hidden">{roleLabel.split(" ")[0]}</span>
          </div>
        )}

        {/* Language Switcher */}
        <Button
          variant="ghost"
          size="sm"
          onClick={toggleLanguage}
          className="h-8 gap-1.5 px-2 text-xs font-medium"
          title={t("nav.switchLanguage")}
        >
          <Globe className="size-3.5" />
          <span className="uppercase">{i18n.language || "vi"}</span>
        </Button>

        {/* Theme Toggle */}
        <Button
          variant="ghost"
          size="icon"
          className="size-8"
          onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
          title={t("nav.toggleTheme")}
        >
          {theme === "dark" ? (
            <Sun className="size-4 text-amber-400" />
          ) : (
            <Moon className="size-4" />
          )}
        </Button>

        {/* Notification Bell */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="relative size-8"
              title={t("nav.notifications")}
            >
              <Bell className="size-4" />
              {unreadCount > 0 && (
                <span className="bg-brand-orange text-2xs absolute -top-0.5 -right-0.5 flex size-4 items-center justify-center rounded-full text-white">
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-80">
            <div className="flex items-center justify-between px-2 py-1.5">
              <DropdownMenuLabel className="p-0 text-xs font-semibold">
                {t("notifications.title")}
              </DropdownMenuLabel>
              {unreadCount > 0 && (
                <button
                  type="button"
                  onClick={handleMarkAllRead}
                  className="text-brand-orange text-2xs font-medium hover:underline"
                >
                  {t("notifications.markAllRead")}
                </button>
              )}
            </div>
            <DropdownMenuSeparator />
            <div className="max-h-80 overflow-y-auto">
              {notifications.length === 0 && (
                <p className="text-muted-foreground px-2 py-4 text-center text-xs">
                  {t("notifications.empty")}
                </p>
              )}
              {notifications.map((n) => {
                const Icon = NOTIFICATION_ICONS[n.type];
                return (
                  <DropdownMenuItem
                    key={n.id}
                    onClick={() => handleNotificationClick(n)}
                    className={cn(
                      "cursor-pointer items-start gap-2 py-2 text-xs",
                      !n.isRead && "bg-muted/40",
                    )}
                  >
                    <Icon className="text-muted-foreground mt-0.5 size-3.5 shrink-0" />
                    <div className="flex-1 space-y-0.5">
                      <p
                        className={cn(
                          "font-medium",
                          n.isRead
                            ? "text-muted-foreground"
                            : "text-foreground",
                        )}
                      >
                        {n.title}
                      </p>
                      <p className="text-muted-foreground text-2xs">
                        {n.message}
                      </p>
                    </div>
                    {!n.isRead && (
                      <span className="bg-brand-orange mt-1 size-1.5 shrink-0 rounded-full" />
                    )}
                  </DropdownMenuItem>
                );
              })}
            </div>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onClick={() => navigate("/notification-settings")}
              className="cursor-pointer justify-center gap-1.5 text-xs font-medium"
            >
              <Settings className="size-3.5" />
              {t("notifications.viewSettings")}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <div className="bg-border mx-1 h-4 w-px" />

        {/* User → click thẳng vào Cài đặt, không qua dropdown */}
        <button
          type="button"
          onClick={() => navigate("/settings")}
          title={t("nav.settings")}
          className="hover:bg-muted flex cursor-pointer items-center gap-2 rounded-md px-1.5 py-1 transition-colors outline-none"
        >
          <div className="bg-brand-orange-soft text-brand-orange border-brand-orange/20 flex size-7 items-center justify-center rounded-full border text-xs font-bold">
            {username.charAt(0).toUpperCase()}
          </div>
          <span className="text-foreground hidden max-w-[120px] truncate text-xs font-semibold sm:inline">
            {username}
          </span>
          <Settings className="text-muted-foreground size-3.5 shrink-0" />
        </button>

        <Button
          variant="ghost"
          size="icon"
          className="size-8 text-rose-500 hover:bg-rose-50 hover:text-rose-600 dark:hover:bg-rose-950/50"
          onClick={handleLogout}
          title={t("nav.logout")}
        >
          <LogOut className="size-4" />
        </Button>
      </div>
    </header>
  );
}

export default Navbar;

import * as React from "react";
import { NavLink } from "react-router-dom";
import {
  LayoutDashboard,
  FileEdit,
  CalendarDays,
  Users,
  BarChart3,
  ShieldAlert,
  ChevronDown,
  FolderKanban,
  FolderPlus,
  LayoutTemplate,
  Hash,
  UserPlus,
  Mail,
  Send,
  Link2,
  CreditCard,
  Sparkles,
  Building2,
  FileBarChart,
  User,
  Inbox,
} from "lucide-react";
import { useTranslation } from "react-i18next";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { MemberRole, Workspace } from "@/types/workspace";
import type { Agency } from "@/types/agency";
import type { SystemRole } from "@/store/authStore";
import { canAccess } from "@/routes/access";

interface NavItem {
  to: string;
  icon: React.ComponentType<{ className?: string }>;
  labelKey: string;
  /** Chỉ hiện khi role hiện tại là CLIENT — cần currentAgencyId để build URL. */
  clientOnly?: boolean;
  /** URL cần currentAgencyId để build (thay {agencyId} trong `to`) — ẩn nếu chưa có agency active. */
  agencyScoped?: boolean;
  /** Ẩn hẳn với role CLIENT (client không phải nhân sự agency nội bộ). */
  hiddenForClient?: boolean;
}

interface NavSection {
  key: string;
  titleKey: string;
  items: NavItem[];
}

const NAV_SECTIONS: NavSection[] = [
  {
    key: "overview",
    titleKey: "nav.sections.overview",
    items: [
      { to: "/dashboard", icon: LayoutDashboard, labelKey: "nav.dashboard" },
      { to: "/analytics", icon: BarChart3, labelKey: "nav.analytics" },
    ],
  },
  {
    key: "create",
    titleKey: "nav.sections.create",
    items: [
      { to: "/requests", icon: FileEdit, labelKey: "nav.requests" },
      { to: "/editor", icon: FileEdit, labelKey: "nav.editor" },
      { to: "/templates", icon: LayoutTemplate, labelKey: "nav.templates" },
      { to: "/hashtag-groups", icon: Hash, labelKey: "nav.hashtagGroups" },
      { to: "/calendar", icon: CalendarDays, labelKey: "nav.calendar" },
      { to: "/library", icon: FolderKanban, labelKey: "nav.library" },
      { to: "/publish", icon: Send, labelKey: "nav.publish" },
    ],
  },
  {
    key: "manage",
    titleKey: "nav.sections.manage",
    items: [
      {
        to: "/agency/{agencyId}",
        icon: Building2,
        labelKey: "nav.agencySub.profile",
        agencyScoped: true,
        hiddenForClient: true,
      },
      {
        to: "/agency/{agencyId}/members",
        icon: Users,
        labelKey: "nav.agencySub.members",
        agencyScoped: true,
        hiddenForClient: true,
      },
      {
        to: "/agency/{agencyId}/stats",
        icon: BarChart3,
        labelKey: "nav.agencySub.stats",
        agencyScoped: true,
        hiddenForClient: true,
      },
      {
        to: "/agency/invitations",
        icon: Inbox,
        labelKey: "nav.agencyInvitationInbox",
        hiddenForClient: true,
      },
      { to: "/invitations", icon: Mail, labelKey: "nav.invitations" },
      { to: "/clients", icon: Building2, labelKey: "nav.clients" },
      { to: "/portal", icon: Users, labelKey: "nav.portal" },
      {
        to: "/client-profile",
        icon: User,
        labelKey: "nav.clientProfile",
        clientOnly: true,
      },
      {
        to: "/social-accounts",
        icon: Link2,
        labelKey: "nav.socialAccounts",
      },
      {
        to: "/subscription/plans",
        icon: CreditCard,
        labelKey: "nav.subscription",
      },
      {
        to: "/ai-studio/ambassadors",
        icon: Sparkles,
        labelKey: "nav.aiStudio",
      },
      { to: "/reports", icon: FileBarChart, labelKey: "nav.reports" },
    ],
  },
  {
    key: "system",
    titleKey: "nav.sections.system",
    items: [{ to: "/admin", icon: ShieldAlert, labelKey: "nav.admin" }],
  },
];

export interface SidebarProps {
  collapsed: boolean;
  role?: MemberRole | null;
  systemRole?: SystemRole | null;
  workspaces: Workspace[];
  activeWorkspace: Workspace | null;
  onSwitchWorkspace: (agencyId: string, workspaceId: string) => void;
  className?: string;
  onMobileItemClick?: () => void;
  /** Đang chọn 1 agency cụ thể hay chưa — chưa chọn agency thì không có
   * ngữ cảnh để lọc workspace, nên ẩn hẳn ô chọn workspace. */
  hasAgency?: boolean;
  /** Toàn bộ agency user thuộc về, để build dropdown lồng nhau agency→workspace. */
  agencyList: Agency[];
  /** Toàn bộ workspace (không lọc theo agency), để nhóm theo từng agency trong dropdown. */
  allWorkspaces: Workspace[];
  currentAgencyId: string | null;
  onSwitchAgency: (agencyId: string) => void;
}

export function Sidebar({
  collapsed,
  role = null,
  systemRole = null,
  workspaces,
  activeWorkspace,
  onSwitchWorkspace,
  className,
  onMobileItemClick,
  hasAgency = false,
  agencyList,
  allWorkspaces,
  currentAgencyId,
  onSwitchAgency,
}: SidebarProps) {
  const { t } = useTranslation();
  const [expandedAgencyId, setExpandedAgencyId] = React.useState<string | null>(
    currentAgencyId,
  );
  const currentAgencyName =
    agencyList.find((a) => a.id === currentAgencyId)?.name ?? null;
  const clientWorkspaces = allWorkspaces.filter((ws) => ws.myRole === "CLIENT");
  // ADMIN chỉ thao tác qua Admin Panel — không vận hành nội dung/workspace,
  // nên chỉ thấy mục "system". Ở agency-level (chưa chọn workspace cụ thể),
  // "create" (editor/calendar/publish...) cần context 1 workspace nên ẩn,
  // chỉ còn "manage" (agency profile/members/stats).
  const visibleSectionKeys: string[] | null =
    systemRole === "ADMIN" ? ["system"] : !activeWorkspace ? ["manage"] : null; // null = không lọc theo section, giữ tất cả

  // Filter sections and items based on role permission
  const filteredSections = NAV_SECTIONS.filter(
    (section) =>
      !visibleSectionKeys || visibleSectionKeys.includes(section.key),
  )
    .map((section) => {
      const items = section.items
        .filter((item) => canAccess(item.to, systemRole, role))
        .filter((item) => !item.hiddenForClient || role !== "CLIENT")
        .filter((item) => !item.clientOnly || role === "CLIENT")
        .filter((item) => !item.agencyScoped || currentAgencyId)
        .map((item) => {
          if (item.clientOnly && currentAgencyId) {
            return {
              ...item,
              to: `/client-profile?agencyId=${currentAgencyId}`,
            };
          }
          if (item.agencyScoped && currentAgencyId) {
            return {
              ...item,
              to: item.to.replace("{agencyId}", currentAgencyId),
            };
          }
          return item;
        });

      // Members link needs a dynamic workspaceId path — only add once a
      // workspace is active, and only for roles that manage membership.
      if (
        section.key === "manage" &&
        activeWorkspace &&
        canAccess(`/workspaces/${activeWorkspace.id}/members`, systemRole, role)
      ) {
        items.push({
          to: `/workspaces/${activeWorkspace.id}/members`,
          icon: UserPlus,
          labelKey: "nav.members",
        });
      }

      return { ...section, items };
    })
    .filter((section) => section.items.length > 0);

  return (
    <div
      className={cn(
        "flex h-full flex-col transition-all duration-200 select-none",
        collapsed ? "w-[60px]" : "w-[220px]",
        className,
      )}
      style={{
        background: "hsl(var(--sidebar, 240 6% 4%))",
        color: "hsl(var(--sidebar-foreground, 0 0% 98%))",
        borderRight: "1px solid hsl(var(--sidebar-border, 240 5% 15%))",
      }}
    >
      {/* Logo Area */}
      <div
        className={cn(
          "flex h-14 shrink-0 items-center border-b px-3",
          collapsed ? "justify-center" : "gap-2.5",
        )}
        style={{ borderColor: "hsl(var(--sidebar-border, 240 5% 15%))" }}
      >
        <div
          className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md"
          style={{ background: "hsl(var(--brand-orange, 15 88% 55%))" }}
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <circle cx="8" cy="8" r="2.2" fill="white" />
            <circle cx="2.5" cy="4" r="1.5" fill="white" />
            <circle cx="13.5" cy="4" r="1.5" fill="white" />
            <circle cx="2.5" cy="12" r="1.5" fill="white" />
            <circle cx="13.5" cy="12" r="1.5" fill="white" />
            <line
              x1="5.8"
              y1="7"
              x2="3.5"
              y2="5"
              stroke="white"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <line
              x1="10.2"
              y1="7"
              x2="12.5"
              y2="5"
              stroke="white"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <line
              x1="5.8"
              y1="9"
              x2="3.5"
              y2="11"
              stroke="white"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
            <line
              x1="10.2"
              y1="9"
              x2="12.5"
              y2="11"
              stroke="white"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
          </svg>
        </div>
        {!collapsed && (
          <span className="font-sans text-sm font-bold tracking-tight text-white">
            Brand
            <span style={{ color: "hsl(var(--brand-orange, 15 88% 55%))" }}>
              Hub
            </span>
          </span>
        )}
      </div>

      {/* Agency → Workspace switcher — 1 dropdown lồng nhau, luôn hiện để có nơi tạo mới. */}
      <div
        className="shrink-0 border-b"
        style={{ borderColor: "hsl(var(--sidebar-border, 240 5% 15%))" }}
      >
