import { useEffect, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import { CheckCircle2, XCircle } from "lucide-react";
import { toast } from "sonner";
import { agencyService } from "@/services/agencyService";
import { extractErrorMessage } from "@/utils/error";

export function AcceptInvitationPage() {
  const [searchParams] = useSearchParams();
  const token = searchParams.get("token");
  const navigate = useNavigate();
  const { t } = useTranslation();
  const [status, setStatus] = useState<"loading" | "success" | "error">(
    "loading",
  );
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!token) {
      setStatus("error");
      setMessage(t("agency.accept.missingToken"));
      return;
    }
    agencyService
      .acceptInvitation(token)
      .then(() => {
        setStatus("success");
        toast.success(t("agency.accept.successToast"));
        setTimeout(() => navigate("/agency"), 1200);
      })
      .catch((err: unknown) => {
        setStatus("error");
        setMessage(extractErrorMessage(err, t("agency.accept.invalid")));
      });
  }, [token, navigate, t]);

  return (
    <div className="flex min-h-screen items-center justify-center px-4">
      <div className="w-full max-w-sm rounded-2xl border p-8 text-center shadow-sm">
        {status === "loading" && (
          <p className="text-muted-foreground text-sm">
            {t("agency.accept.loading")}
          </p>
        )}
        {status === "success" && (
          <>
            <CheckCircle2 className="mx-auto size-10 text-green-600" />
            <p className="mt-3 font-semibold">
              {t("agency.accept.successTitle")}
            </p>
            <p className="text-muted-foreground mt-1 text-sm">
              {t("agency.accept.redirecting")}
            </p>
          </>
        )}
        {status === "error" && (
          <>
            <XCircle className="text-destructive mx-auto size-10" />
            <p className="mt-3 font-semibold">
              {t("agency.accept.failedTitle")}
            </p>
            <p className="text-muted-foreground mt-1 text-sm">{message}</p>
            <Button
              className="bg-brand-orange hover:bg-brand-orange/90 mt-4 cursor-pointer text-white"
              onClick={() => navigate("/agency")}
            >
              {t("agency.accept.back")}
            </Button>
          </>
        )}
      </div>
    </div>
  );
}

export default AcceptInvitationPage;

import { useEffect, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  Briefcase,
  Building2,
  Globe,
  Link2,
  MapPin,
  Pencil,
  Phone,
  Plus,
  TriangleAlert,
  Upload,
  User,
  Users,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select } from "@/components/ui/select";
import { ProvinceSelect } from "@/components/ui/province-select";
import { RichTextInput } from "@/components/ui/rich-text-input";
import { agencyService } from "@/services/agencyService";
import { useAuthStore } from "@/store/authStore";
import { useAgencyStore } from "@/store/agencyStore";
import { extractErrorMessage } from "@/utils/error";
import { AGENCY_CATEGORIES, COMPANY_SIZES } from "@/pages/agency/constants";
import { LOGO_ICON_OPTIONS, getLogoIcon } from "@/pages/agency/logoIcons";
import { AgencyOrgChart } from "@/pages/agency/components/AgencyOrgChart";
import type { Agency, AgencyCategory, CompanySize } from "@/types/agency";

const CURRENT_YEAR = new Date().getFullYear();
const URL_RE = /^https?:\/\/.+/i;
const PHONE_RE = /^[0-9+\-\s()]{6,20}$/;

export function AgencyDetailPage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const currentUser = useAuthStore((s) => s.user);
  const setCurrentAgencyId = useAgencyStore((s) => s.setCurrentAgencyId);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (id) setCurrentAgencyId(id);
  }, [id, setCurrentAgencyId]);

  const [agency, setAgency] = useState<Agency | null>(null);
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [uploadingLogo, setUploadingLogo] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [confirmName, setConfirmName] = useState("");
  const [deleting, setDeleting] = useState(false);
  const [restoring, setRestoring] = useState(false);

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [logoUrl, setLogoUrl] = useState("");
  const [category, setCategory] = useState<AgencyCategory | "">("");
  const [companySize, setCompanySize] = useState<CompanySize | "">("");
  const [website, setWebsite] = useState("");
  const [phone, setPhone] = useState("");
  const [location, setLocation] = useState("");
  const [brandColor, setBrandColor] = useState("#f05a28");
  const [logoIcon, setLogoIcon] = useState(LOGO_ICON_OPTIONS[0].name);
  const [tagline, setTagline] = useState("");
  const [foundedYear, setFoundedYear] = useState("");
  const [facebookUrl, setFacebookUrl] = useState("");
  const [linkedinUrl, setLinkedinUrl] = useState("");
  const [instagramUrl, setInstagramUrl] = useState("");

  type FieldErrors = Partial<
    Record<
      | "name"
      | "website"
      | "phone"
      | "facebookUrl"
      | "linkedinUrl"
      | "instagramUrl"
      | "foundedYear",
      string
    >
  >;
  const [errors, setErrors] = useState<FieldErrors>({});

  const validateField = (field: keyof FieldErrors, value: string) => {
    let message: string | undefined;
    switch (field) {
      case "name":
        if (!value.trim()) message = t("agency.detail.errors.nameRequired");
        break;
      case "website":
      case "facebookUrl":
      case "linkedinUrl":
      case "instagramUrl":
        if (value.trim() && !URL_RE.test(value.trim()))
          message = t("agency.detail.errors.invalidUrl");
        break;
      case "phone":
        if (value.trim() && !PHONE_RE.test(value.trim()))
          message = t("agency.detail.errors.invalidPhone");
        break;
      case "foundedYear":
        if (value) {
          const y = Number(value);
          if (!Number.isFinite(y) || y < 1900 || y > CURRENT_YEAR)
            message = t("agency.detail.errors.invalidYear", {
              max: CURRENT_YEAR,
            });
        }
        break;
    }
    setErrors((prev) => ({ ...prev, [field]: message }));
    return !message;
  };

  const hasErrors = Object.values(errors).some(Boolean);

  const applyAgency = (a: Agency) => {
    setAgency(a);
    setName(a.name);
    setDescription(a.description ?? "");
    setLogoUrl(a.logoUrl ?? "");
    setCategory(a.category ?? "");
    setCompanySize(a.companySize ?? "");
    setWebsite(a.website ?? "");
    setPhone(a.phone ?? "");
    setLocation(a.location ?? "");
    setBrandColor(a.brandColor ?? "#f05a28");
    setLogoIcon(a.logoIcon ?? LOGO_ICON_OPTIONS[0].name);
    setTagline(a.tagline ?? "");
    setFoundedYear(a.foundedYear ? String(a.foundedYear) : "");
    setFacebookUrl(a.facebookUrl ?? "");
    setLinkedinUrl(a.linkedinUrl ?? "");
    setInstagramUrl(a.instagramUrl ?? "");
  };

  useEffect(() => {
    if (!id) return;
    agencyService
      .getById(id)
      .then(({ data }) => applyAgency(data.data))
      .catch((err: unknown) =>
        toast.error(extractErrorMessage(err, t("agency.errors.loadOneFailed"))),
      )
      .finally(() => setLoading(false));
  }, [id, t]);

  const isOwner =
    !!agency && !!currentUser && agency.ownerId === currentUser.id;

  const handleSave = async () => {
    if (!id) return;
    setSaving(true);
    try {
      const yearNum = foundedYear ? Number(foundedYear) : undefined;
      const { data } = await agencyService.update(id, {
        name: name.trim(),
        description: description.trim() || undefined,
        logoUrl: logoUrl.trim() || undefined,
        category: category || undefined,
        companySize: companySize || undefined,
        website: website.trim() || undefined,
        phone: phone.trim() || undefined,
        location: location.trim() || undefined,
        brandColor: brandColor || undefined,
        logoIcon: logoIcon || undefined,
        tagline: tagline.trim() || undefined,
        foundedYear:
          yearNum && yearNum >= 1900 && yearNum <= CURRENT_YEAR
            ? yearNum
            : undefined,
        facebookUrl: facebookUrl.trim() || undefined,
        linkedinUrl: linkedinUrl.trim() || undefined,
        instagramUrl: instagramUrl.trim() || undefined,
      });
      applyAgency(data.data);
      setIsEditing(false);
      toast.success(t("agency.detail.saveSuccess"));
    } catch (err: unknown) {
      toast.error(extractErrorMessage(err, t("agency.errors.updateFailed")));
    } finally {
      setSaving(false);
    }
  };

  const handleCancelEdit = () => {
    if (!agency) return;
    applyAgency(agency);
    setErrors({});
    setIsEditing(false);
  };

  const handleDelete = async () => {
    if (!id) return;
    setDeleting(true);
    try {
      await agencyService.remove(id);
      toast.success(t("agency.detail.danger.deleteSuccess"));
      navigate("/agency");
    } catch (err: unknown) {
      toast.error(
        extractErrorMessage(err, t("agency.detail.danger.deleteError")),
      );
    } finally {
      setDeleting(false);
      setDeleteOpen(false);
      setConfirmName("");
    }
  };

  const handleRestore = async () => {
    if (!id) return;
    setRestoring(true);
    try {
      const { data } = await agencyService.restore(id);
      applyAgency(data.data);
      toast.success(t("agency.detail.danger.restoreSuccess"));
    } catch (err: unknown) {
      toast.error(
        extractErrorMessage(err, t("agency.detail.danger.restoreError")),
      );
    } finally {
      setRestoring(false);
    }
  };

  const handleLogoFileChange = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file || !id) return;
    setUploadingLogo(true);
    try {
      const { data } = await agencyService.uploadLogo(id, file);
      applyAgency(data.data);
      toast.success(t("agency.detail.uploadLogoSuccess"));
    } catch (err: unknown) {
      toast.error(
        extractErrorMessage(err, t("agency.detail.uploadLogoFailed")),
      );
    } finally {
      setUploadingLogo(false);
    }
  };

  if (loading) return null;
  if (!agency) return null;

  const FallbackIcon = getLogoIcon(agency.logoIcon);
  const isDeleted = agency.status === "SOFT_DELETED";

  return (
    <div className="container mx-auto max-w-6xl p-4 pb-24 md:p-8">
      <div className="min-w-0 space-y-10">
        {isDeleted && isOwner && (
          <div className="bg-card flex items-center justify-between rounded-xl border border-red-200 p-4 dark:border-red-900/50">
            <div className="flex items-center gap-2">
              <TriangleAlert className="size-4 text-rose-500" />
              <p className="text-foreground text-sm font-medium">
                {t("agency.detail.danger.restoreHint")}
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              loading={restoring}
              onClick={handleRestore}
            >
              {t("agency.detail.danger.restoreButton")}
            </Button>
          </div>
        )}
        <section className="space-y-6">
          <div className="bg-card flex flex-col gap-4 rounded-xl border p-5 shadow-xs">
            <div className="flex items-center gap-3">
              <div
                className="flex size-12 shrink-0 items-center justify-center overflow-hidden rounded-lg"
                style={{
                  background: agency.logoUrl
                    ? undefined
                    : `${agency.brandColor ?? "#f05a28"}1a`,
                  color: agency.brandColor ?? undefined,
                }}
              >
                {agency.logoUrl ? (
                  <img
                    src={agency.logoUrl}
                    alt={agency.name}
                    className="size-full object-cover"
                  />
                ) : (
                  <FallbackIcon
                    className="size-6"
                    style={{ color: agency.brandColor ?? undefined }}
                  />
                )}
              </div>
              <div className="min-w-0">
                <p className="truncate text-base font-semibold">
                  {agency.name}
                </p>
                {agency.tagline && (
                  <p className="text-muted-foreground truncate text-xs">
                    {agency.tagline}
                  </p>
                )}
                {!isOwner && (
                  <p className="text-muted-foreground text-xs">
                    {t("agency.detail.ownerOnlyHint")}
                  </p>
                )}
              </div>
            </div>

            {isEditing ? (
              <div className="space-y-4">
                <Input
                  label={t("agency.create.nameLabel")}
                  placeholder={t("agency.create.namePlaceholder")}
                  value={name}
                  onChange={(e) => {
                    setName(e.target.value);
                    validateField("name", e.target.value);
                  }}
                  error={errors.name}
                  required
                />

                <div className="flex flex-col gap-1.5">
                  <Label className="text-xs font-semibold tracking-wide">
                    {t("agency.detail.logoLabel")}
                  </Label>
                  <div className="flex items-center gap-3">
                    <div
                      className="flex size-14 shrink-0 items-center justify-center overflow-hidden rounded-lg"
                      style={{
                        background: logoUrl ? undefined : `${brandColor}1a`,
                      }}
                    >
                      {logoUrl ? (
                        <img
                          src={logoUrl}
                          alt=""
                          className="size-full object-cover"
                        />
                      ) : (
                        (() => {
                          const Icon = getLogoIcon(logoIcon);
                          return (
                            <Icon
                              className="size-6"
                              style={{ color: brandColor }}
                            />
                          );
                        })()
                      )}
                    </div>
                    <input
                      ref={logoInputRef}
                      type="file"
                      accept="image/*"
                      hidden
                      onChange={handleLogoFileChange}
                    />
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      loading={uploadingLogo}
                      className="cursor-pointer gap-1.5"
                      onClick={() => logoInputRef.current?.click()}
                    >
                      <Upload className="size-3.5" />
                      {t("agency.detail.uploadLogoButton")}
                    </Button>
                  </div>
                  <p className="text-muted-foreground text-2xs">
                    {t("agency.detail.logoPostSaveHint")}
                  </p>
                </div>

                <RichTextInput
                  label={t("agency.create.descriptionLabel")}
                  placeholder={t("agency.create.descriptionPlaceholder")}
                  value={description}
                  onChange={setDescription}
                />
                <Input
                  label={t("agency.create.taglineLabel")}
                  placeholder={t("agency.create.taglinePlaceholder")}
                  maxLength={140}
                  value={tagline}
                  onChange={(e) => setTagline(e.target.value)}
                />
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-xs font-semibold tracking-wide">
                      {t("agency.create.categoryLabel")}
                    </Label>
                    <Select
                      value={category}
                      onChange={(e) =>
                        setCategory(e.target.value as AgencyCategory | "")
                      }
                    >
                      <option value="">
                        {t("agency.create.categoryPlaceholder")}
                      </option>
                      {AGENCY_CATEGORIES.map((c) => (
                        <option key={c} value={c}>
                          {t(`agency.category.${c}`)}
                        </option>
                      ))}
                    </Select>
                  </div>
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-xs font-semibold tracking-wide">
                      {t("agency.create.companySizeLabel")}
                    </Label>
                    <Select
                      value={companySize}
                      onChange={(e) =>
                        setCompanySize(e.target.value as CompanySize | "")
                      }
                    >
                      <option value="">
                        {t("agency.create.companySizePlaceholder")}
                      </option>
                      {COMPANY_SIZES.map((s) => (
                        <option key={s} value={s}>
                          {t(`agency.companySize.${s}`)}
                        </option>
                      ))}
                    </Select>
