                    label={t("agency.create.phoneLabel")}
                    placeholder={t("agency.create.phonePlaceholder")}
                    value={phone}
                    onChange={(e) => {
                      setPhone(e.target.value);
                      validateField("phone", e.target.value);
                    }}
                    error={errors.phone}
                  />
                  <ProvinceSelect
                    label={t("agency.create.locationLabel")}
                    value={location}
                    onChange={setLocation}
                  />
                </div>
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="flex flex-col gap-1.5">
                    <Label className="text-xs font-semibold tracking-wide">
                      {t("agency.create.brandColorLabel")}
                    </Label>
                    <input
                      type="color"
                      value={brandColor}
                      onChange={(e) => setBrandColor(e.target.value)}
                      className="border-input h-9 w-full cursor-pointer rounded-md border"
                    />
                  </div>
                  <Input
                    label={t("agency.create.foundedYearLabel")}
                    type="number"
                    min={1900}
                    max={CURRENT_YEAR}
                    value={foundedYear}
                    onChange={(e) => {
                      setFoundedYear(e.target.value);
                      validateField("foundedYear", e.target.value);
                    }}
                    error={errors.foundedYear}
                  />
                </div>
                <div className="flex flex-col gap-1.5">
                  <Label className="text-xs font-semibold tracking-wide">
                    {t("agency.create.logoIconLabel")}
                  </Label>
                  <div className="flex flex-wrap gap-2">
                    {LOGO_ICON_OPTIONS.map(({ name: iconName, Icon }) => (
                      <button
                        key={iconName}
                        type="button"
                        onClick={() => setLogoIcon(iconName)}
                        className={cn(
                          "flex size-10 cursor-pointer items-center justify-center rounded-lg border transition-colors",
                          logoIcon === iconName
                            ? "border-brand-orange bg-brand-orange/10 text-brand-orange"
                            : "text-muted-foreground hover:bg-muted",
                        )}
                      >
                        <Icon className="size-5" />
                      </button>
                    ))}
                  </div>
                </div>
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
                  <Input
                    label={t("agency.create.facebookUrlLabel")}
                    placeholder="https://facebook.com/..."
                    value={facebookUrl}
                    onChange={(e) => {
                      setFacebookUrl(e.target.value);
                      validateField("facebookUrl", e.target.value);
                    }}
                    error={errors.facebookUrl}
                  />
                  <Input
                    label={t("agency.create.linkedinUrlLabel")}
                    placeholder="https://linkedin.com/..."
                    value={linkedinUrl}
                    onChange={(e) => {
                      setLinkedinUrl(e.target.value);
                      validateField("linkedinUrl", e.target.value);
                    }}
                    error={errors.linkedinUrl}
                  />
                  <Input
                    label={t("agency.create.instagramUrlLabel")}
                    placeholder="https://instagram.com/..."
                    value={instagramUrl}
                    onChange={(e) => {
                      setInstagramUrl(e.target.value);
                      validateField("instagramUrl", e.target.value);
                    }}
                    error={errors.instagramUrl}
                  />
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    onClick={handleCancelEdit}
                    className="cursor-pointer"
                  >
                    {t("agency.detail.cancelButton")}
                  </Button>
                  <Button
                    loading={saving}
                    disabled={hasErrors || !name.trim()}
                    onClick={handleSave}
                    className="bg-brand-orange hover:bg-brand-orange/90 cursor-pointer text-white"
                  >
                    {t("agency.detail.saveButton")}
                  </Button>
                </div>
              </div>
            ) : (
              <>
                {agency.description ? (
                  <div
                    className="prose prose-sm dark:prose-invert text-muted-foreground max-w-none text-sm"
                    dangerouslySetInnerHTML={{ __html: agency.description }}
                  />
                ) : (
                  <p className="text-muted-foreground text-sm">—</p>
                )}
                <div className="grid grid-cols-1 gap-3 border-t pt-4 sm:grid-cols-2">
                  <div className="flex items-center gap-2 text-sm">
                    <Briefcase className="text-muted-foreground size-4 shrink-0" />
                    <span>
                      {agency.category
                        ? t(`agency.category.${agency.category}`)
                        : "—"}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <Users className="text-muted-foreground size-4 shrink-0" />
                    <span>
                      {agency.companySize
                        ? t(`agency.companySize.${agency.companySize}`)
                        : "—"}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <Globe className="text-muted-foreground size-4 shrink-0" />
                    <span className="truncate">{agency.website || "—"}</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <Phone className="text-muted-foreground size-4 shrink-0" />
                    <span>{agency.phone || "—"}</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <MapPin className="text-muted-foreground size-4 shrink-0" />
                    <span>{agency.location || "—"}</span>
                  </div>
                  {agency.foundedYear && (
                    <div className="flex items-center gap-2 text-sm">
                      <Building2 className="text-muted-foreground size-4 shrink-0" />
                      <span>{agency.foundedYear}</span>
                    </div>
                  )}
                </div>
                {(agency.facebookUrl ||
                  agency.linkedinUrl ||
                  agency.instagramUrl) && (
                  <div className="flex items-center gap-2 border-t pt-4">
                    {agency.facebookUrl && (
                      <a
                        href={agency.facebookUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-muted-foreground hover:text-foreground"
                      >
                        <Link2 className="size-4" />
                      </a>
                    )}
                    {agency.linkedinUrl && (
                      <a
                        href={agency.linkedinUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-muted-foreground hover:text-foreground"
                      >
                        <Link2 className="size-4" />
                      </a>
                    )}
                    {agency.instagramUrl && (
                      <a
                        href={agency.instagramUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-muted-foreground hover:text-foreground"
                      >
                        <Link2 className="size-4" />
                      </a>
                    )}
                  </div>
                )}
                {isOwner && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-fit cursor-pointer gap-1.5"
                    onClick={() => setIsEditing(true)}
                  >
                    <Pencil className="size-3.5" />
                    {t("agency.detail.editButton")}
                  </Button>
                )}
              </>
            )}
          </div>

          {isOwner && !isEditing && (
            <div className="bg-brand-orange-soft flex flex-col gap-3 rounded-xl border border-dashed p-5">
              <p className="text-sm font-semibold">
                {t("agency.detail.createWorkspaceCta")}
              </p>
              <Button
                className="bg-brand-orange hover:bg-brand-orange/90 w-fit cursor-pointer gap-1.5 text-white"
                onClick={() => navigate(`/workspaces/create?agencyId=${id}`)}
              >
                <Plus className="size-4" />
                {t("workspace.create.title")}
              </Button>
            </div>
          )}

          {!isEditing && (
            <Button
              variant="outline"
              className="w-fit cursor-pointer gap-1.5"
              onClick={() => navigate(`/client-profile?agencyId=${id}`)}
            >
              <User className="size-3.5" />
              {t("agency.detail.viewClientProfile")}
            </Button>
          )}

          <Button
            variant="outline"
            className="cursor-pointer"
            onClick={() => navigate("/agency")}
          >
            {t("agency.detail.back")}
          </Button>

          {isOwner && !isDeleted && !isEditing && (
            <div className="bg-card max-w-sm rounded-xl border border-red-200 p-6 dark:border-red-900/50">
              <h3 className="text-foreground flex items-center gap-2 text-sm font-semibold">
                <TriangleAlert className="size-4 text-rose-500" />
                {t("agency.detail.danger.title")}
              </h3>
              <p className="text-muted-foreground mt-2 text-xs">
                {t("agency.detail.danger.deleteHint")}
              </p>
              <Button
                variant="outline"
                size="sm"
                className="mt-4 border-rose-300 text-rose-600 hover:bg-rose-50 dark:border-rose-800 dark:hover:bg-rose-950/40"
                onClick={() => setDeleteOpen(true)}
              >
                {t("agency.detail.danger.deleteButton")}
              </Button>
            </div>
          )}
        </section>

        <div className="border-border border-t" />

        <section className="space-y-4">
          <div>
            <h2 className="text-foreground text-lg font-semibold">
              {t("agency.detail.nav.members")}
            </h2>
            <p className="text-muted-foreground text-sm">
              {t("agency.detail.membersPreviewDescription")}
            </p>
          </div>
          {id && <AgencyOrgChart agencyId={id} />}
          <Button
            variant="outline"
            size="sm"
            className="cursor-pointer gap-1.5"
            onClick={() => navigate(`/agency/${id}/members`)}
          >
            <User className="size-3.5" />
            {t("agency.detail.viewAllMembers")}
          </Button>
        </section>
      </div>

      {deleteOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="border-border bg-card w-full max-w-sm space-y-4 rounded-xl border p-6 shadow-2xl">
            <div className="flex items-center gap-2">
              <TriangleAlert className="size-5 text-rose-500" />
              <h3 className="text-foreground text-sm font-semibold">
                {t("agency.detail.danger.confirmTitle")}
              </h3>
            </div>
            <p className="text-muted-foreground text-xs">
              {t("agency.detail.danger.confirmBody")}
            </p>
            <Input
              value={confirmName}
              onChange={(e) => setConfirmName(e.target.value)}
              placeholder={agency.name}
            />
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  setDeleteOpen(false);
                  setConfirmName("");
                }}
              >
                {t("agency.detail.danger.cancel")}
              </Button>
              <Button
                variant="destructive"
                size="sm"
                loading={deleting}
                disabled={confirmName !== agency.name || deleting}
                onClick={handleDelete}
              >
                {t("agency.detail.danger.confirmDelete")}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default AgencyDetailPage;

