import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select } from "@/components/ui/select";
import { Settings2, UserPlus, Trash2, ShieldCheck } from "lucide-react";
import type {
  Client,
  ClientContact,
  ClientContactRole,
  ClientPreferences,
  UpdateClientSettingsDTO,
} from "../types/client";

interface ClientSettingsModalProps {
  isOpen: boolean;
  client: Client | null;
  onClose: () => void;
  onSubmit: (id: string, dto: UpdateClientSettingsDTO) => Promise<void>;
}

const CONTACT_ROLES: ClientContactRole[] = [
  "MARKETING_LEAD",
  "APPROVER",
  "FINANCE",
  "LEGAL",
];

const DEFAULT_PREFERENCES: ClientPreferences = {
  notifyOnNewRequest: true,
  notifyOnPublish: true,
  requireClientApprovalBeforePublish: false,
  preferredLanguage: "vi",
};

export function ClientSettingsModal({
  isOpen,
  client,
  onClose,
  onSubmit,
}: ClientSettingsModalProps) {
  const { t } = useTranslation();
  const [contacts, setContacts] = useState<ClientContact[]>([]);
  const [preferences, setPreferences] =
    useState<ClientPreferences>(DEFAULT_PREFERENCES);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (client) {
      setContacts(client.contacts ?? []);
      setPreferences(client.preferences ?? DEFAULT_PREFERENCES);
    }
  }, [client]);

  function addContact() {
    setContacts((prev) => [
      ...prev,
      {
        id: `ct-new-${Date.now()}`,
        name: "",
        email: "",
        role: "MARKETING_LEAD",
        canApproveContent: false,
      },
    ]);
  }

  function updateContact(id: string, patch: Partial<ClientContact>) {
    setContacts((prev) =>
      prev.map((c) => (c.id === id ? { ...c, ...patch } : c)),
    );
  }

  function removeContact(id: string) {
    setContacts((prev) => prev.filter((c) => c.id !== id));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!client) return;
    setIsSaving(true);
    try {
      await onSubmit(client.id, { contacts, preferences });
      onClose();
    } finally {
      setIsSaving(false);
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[560px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base font-bold">
            <Settings2 className="text-brand-orange size-4" />
            {t("client.settings.modalTitle")}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-5 py-2">
          {client && (
            <div className="bg-muted/40 space-y-1 rounded-lg p-3 text-xs">
              <span className="text-muted-foreground block">
                {t("client.settings.appliedBrand")}
              </span>
              <strong className="text-foreground text-sm font-bold">
                {client.name}
              </strong>
            </div>
          )}

          {/* Contact roles within the client's business */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label className="text-xs font-semibold">
                {t("client.settings.contactsLabel")}
              </Label>
              <Button
                variant="ghost"
                type="button"
                onClick={addContact}
                className="hover:bg-brand-orange-soft hover:text-brand-orange text-2xs text-muted-foreground flex h-auto cursor-pointer items-center gap-1 rounded-lg px-2 py-1 font-medium transition-colors"
              >
                <UserPlus className="size-3.5" />
                {t("client.settings.addContact")}
              </Button>
            </div>

            {contacts.length === 0 && (
              <p className="text-muted-foreground text-2xs italic">
                {t("client.settings.contactsEmpty")}
              </p>
            )}

            <div className="space-y-2">
              {contacts.map((contact) => (
                <div
                  key={contact.id}
                  className="border-border grid grid-cols-1 gap-2 rounded-lg border p-2.5 sm:grid-cols-[1fr_1fr_auto_auto]"
                >
                  <Input
                    value={contact.name}
                    onChange={(e) =>
                      updateContact(contact.id, { name: e.target.value })
                    }
                    placeholder={t("client.settings.contactNamePlaceholder")}
                    className="text-xs"
                  />
                  <Input
                    type="email"
                    value={contact.email}
                    onChange={(e) =>
                      updateContact(contact.id, { email: e.target.value })
                    }
                    placeholder={t("client.settings.contactEmailPlaceholder")}
                    className="text-xs"
                  />
                  <Select
                    value={contact.role}
                    onChange={(e) =>
                      updateContact(contact.id, {
                        role: e.target.value as ClientContactRole,
                      })
                    }
                    className="border-border bg-card text-foreground text-2xs h-auto rounded-lg border px-2"
                  >
                    {CONTACT_ROLES.map((role) => (
                      <option key={role} value={role}>
                        {t(`client.settings.role.${role}`)}
                      </option>
                    ))}
                  </Select>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      title={t("client.settings.canApproveToggle")}
                      onClick={() =>
                        updateContact(contact.id, {
                          canApproveContent: !contact.canApproveContent,
                        })
                      }
                      className={`flex size-7 cursor-pointer items-center justify-center rounded-lg transition-colors ${
                        contact.canApproveContent
                          ? "bg-brand-orange-soft text-brand-orange"
                          : "bg-muted text-muted-foreground"
                      }`}
                    >
                      <ShieldCheck className="size-3.5" />
                    </button>
                    <Button
                      variant="ghost"
                      size="icon"
                      type="button"
                      onClick={() => removeContact(contact.id)}
                      className="flex size-7 cursor-pointer items-center justify-center rounded-lg bg-rose-50 text-rose-600 transition-colors hover:bg-rose-100 dark:bg-rose-950/40"
                    >
                      <Trash2 className="size-3.5" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Preferences distinct per client */}
          <div className="space-y-2">
            <Label className="text-xs font-semibold">
              {t("client.settings.preferencesLabel")}
            </Label>
            <div className="space-y-1.5">
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  checked={preferences.notifyOnNewRequest}
                  onChange={(e) =>
                    setPreferences((prev) => ({
                      ...prev,
                      notifyOnNewRequest: e.target.checked,
                    }))
                  }
                  className="accent-brand-orange size-3.5"
                />
                {t("client.settings.notifyOnNewRequest")}
              </label>
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  checked={preferences.notifyOnPublish}
                  onChange={(e) =>
                    setPreferences((prev) => ({
                      ...prev,
                      notifyOnPublish: e.target.checked,
                    }))
                  }
                  className="accent-brand-orange size-3.5"
                />
                {t("client.settings.notifyOnPublish")}
              </label>
              <label className="flex cursor-pointer items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  checked={preferences.requireClientApprovalBeforePublish}
                  onChange={(e) =>
                    setPreferences((prev) => ({
                      ...prev,
                      requireClientApprovalBeforePublish: e.target.checked,
                    }))
                  }
                  className="accent-brand-orange size-3.5"
                />
                {t("client.settings.requireApproval")}
              </label>
            </div>

            <div className="space-y-1.5 pt-1">
              <Label className="text-xs font-semibold">
                {t("client.settings.languageLabel")}
              </Label>
              <div className="flex gap-2">
                {(["vi", "en"] as const).map((lang) => (
                  <button
                    key={lang}
                    type="button"
                    onClick={() =>
                      setPreferences((prev) => ({
                        ...prev,
                        preferredLanguage: lang,
                      }))
                    }
                    className={`text-2xs cursor-pointer rounded-lg border px-3 py-1.5 font-semibold transition-colors ${
                      preferences.preferredLanguage === lang
                        ? "border-brand-orange bg-brand-orange-soft text-brand-orange"
                        : "border-border text-muted-foreground hover:bg-muted/50"
                    }`}
                  >
                    {lang.toUpperCase()}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <DialogFooter className="pt-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              className="cursor-pointer text-xs"
            >
              {t("client.settings.cancel")}
            </Button>
            <Button
              type="submit"
              size="sm"
              disabled={isSaving}
              className="bg-brand-orange hover:bg-brand-orange/90 cursor-pointer gap-1.5 text-xs text-white"
            >
              {isSaving
                ? t("client.settings.saving")
                : t("client.settings.saveButton")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { useTranslation } from "react-i18next";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type {
  Client,
  UpdateServicePackageDTO,
  PackageTier,
} from "../types/client";
import { Package, Zap } from "lucide-react";

interface ServicePackageModalProps {
  isOpen: boolean;
  client: Client | null;
  onClose: () => void;
  onSubmit: (id: string, dto: UpdateServicePackageDTO) => Promise<void>;
  isLoading?: boolean;
}

export function ServicePackageModal({
  isOpen,
  client,
  onClose,
  onSubmit,
  isLoading = false,
}: ServicePackageModalProps) {
  const { t } = useTranslation();
  const [formData, setFormData] = useState<UpdateServicePackageDTO>({
    packageTier: "GROWTH",
    monthlyPostLimit: 30,
    aiCreditsPerMonth: 200,
    expiryDate: "2026-12-31",
  });

  useEffect(() => {
    if (client?.servicePackage) {
      setFormData({
        packageTier: client.servicePackage.packageTier,
        monthlyPostLimit: client.servicePackage.monthlyPostQuota,
        aiCreditsPerMonth: client.servicePackage.aiCreditsPerMonth || 200,
        expiryDate: client.servicePackage.expiryDate || "2026-12-31",
      });
    }
  }, [client]);

  const handleTierChange = (tier: PackageTier) => {
    const quotaMap: Record<PackageTier, number> = {
      FREE: 5,
      STARTER: 15,
      GROWTH: 30,
      ENTERPRISE: 45,
    };
    setFormData((prev) => ({
      ...prev,
      packageTier: tier,
      monthlyPostLimit: quotaMap[tier],
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!client) return;
    await onSubmit(client.id, formData);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[480px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-base font-bold">
            <Package className="text-brand-orange size-4" />
            {t("client.servicePackage.modalTitle")}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-2">
          {client && (
            <div className="bg-muted/40 space-y-1 rounded-lg p-3 text-xs">
              <span className="text-muted-foreground block">
                {t("client.servicePackage.appliedBrand")}
              </span>
              <strong className="text-foreground text-sm font-bold">
                {client.name}
              </strong>
            </div>
          )}

          {/* Hạng gói dịch vụ */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">
              {t("client.servicePackage.tierLabel")}
            </Label>
            <div className="grid grid-cols-3 gap-2">
              {(["STARTER", "GROWTH", "ENTERPRISE"] as PackageTier[]).map(
                (tier) => (
                  <button
                    key={tier}
                    type="button"
                    onClick={() => handleTierChange(tier)}
                    className={`text-3xs cursor-pointer rounded-lg border p-2.5 text-center font-bold transition-all sm:text-xs ${
                      formData.packageTier === tier
                        ? "border-brand-orange bg-brand-orange-soft text-brand-orange dark:bg-brand-orange/10"
                        : "border-border hover:bg-muted/50 text-foreground"
                    }`}
                  >
                    {tier}
                  </button>
                ),
              )}
            </div>
          </div>

          {/* Quota bài viết & AI credits */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label htmlFor="postLimit" className="text-xs font-semibold">
                {t("client.servicePackage.postLimitLabel")}
              </Label>
              <Input
                id="postLimit"
                type="number"
                value={formData.monthlyPostLimit}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    monthlyPostLimit: Number(e.target.value),
                  })
                }
                className="font-mono text-xs"
              />
            </div>
            <div className="space-y-1.5">
              <Label
                htmlFor="aiCredits"
                className="flex items-center gap-1 text-xs font-semibold"
              >
                <Zap className="size-3 text-amber-500" />{" "}
                {t("client.servicePackage.aiCreditsLabel")}
              </Label>
              <Input
                id="aiCredits"
                type="number"
                value={formData.aiCreditsPerMonth || 200}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    aiCreditsPerMonth: Number(e.target.value),
                  })
                }
                className="font-mono text-xs"
              />
            </div>
          </div>

          {/* Ngày hết hạn gói */}
          <div className="space-y-1.5">
            <Label htmlFor="expiry" className="text-xs font-semibold">
              {t("client.servicePackage.expiryLabel")}
            </Label>
            <Input
              id="expiry"
              type="date"
              value={formData.expiryDate || ""}
              onChange={(e) =>
                setFormData({ ...formData, expiryDate: e.target.value })
              }
              className="text-xs"
            />
          </div>

          <DialogFooter className="pt-3">
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={onClose}
              className="cursor-pointer text-xs"
            >
              {t("client.servicePackage.cancel")}
            </Button>
            <Button
              type="submit"
              size="sm"
              disabled={isLoading}
              className="bg-brand-orange hover:bg-brand-orange/90 cursor-pointer gap-1.5 text-xs text-white"
            >
              {isLoading
                ? t("client.servicePackage.processing")
                : t("client.servicePackage.updateButton")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

