import { useEffect, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuthStore } from "@/store/authStore";
import { authService } from "@/services/authService";
import { dashboardService } from "@/services/mock/mockDashboardService";
import type { AnalyticsOverview, ActivityEvent } from "@/types/analytics";

export function useDashboardData() {
  const navigate = useNavigate();
  const { user, clearAuth } = useAuthStore();

  const [analytics, setAnalytics] = useState<AnalyticsOverview | null>(null);
  const [isAnalyticsLoading, setIsAnalyticsLoading] = useState(true);
  const [isAnalyticsError, setIsAnalyticsError] = useState(false);

  const [activities, setActivities] = useState<ActivityEvent[]>([]);
  const [isActivitiesLoading, setIsActivitiesLoading] = useState(true);
  const [isActivitiesError, setIsActivitiesError] = useState(false);

  const [isRefreshing, setIsRefreshing] = useState(false);

  const fetchAnalytics = useCallback(async () => {
    try {
      setIsAnalyticsError(false);
      const data = await dashboardService.getAnalyticsOverview();
      setAnalytics(data);
    } catch (err) {
      console.error("Failed to fetch analytics overview:", err);
      setIsAnalyticsError(true);
    } finally {
      setIsAnalyticsLoading(false);
    }
  }, []);

  const fetchActivities = useCallback(async () => {
    try {
      setIsActivitiesError(false);
      const feed = await dashboardService.getActivityFeed(0, 10);
      setActivities(feed);
    } catch (err) {
      console.error("Failed to fetch activity feed:", err);
      setIsActivitiesError(true);
    } finally {
      setIsActivitiesLoading(false);
    }
  }, []);

  const loadAllData = useCallback(async () => {
    setIsRefreshing(true);
    await Promise.all([fetchAnalytics(), fetchActivities()]);
    setIsRefreshing(false);
  }, [fetchAnalytics, fetchActivities]);

  useEffect(() => {
    loadAllData();
    const pollingInterval = setInterval(
      () => {
        loadAllData();
      },
      5 * 60 * 1000,
    );

    return () => clearInterval(pollingInterval);
  }, [loadAllData]);

  const handleLogout = () => {
    // FR 3.2.8: blacklist token server-side (BR-14), same as Navbar.handleLogout.
    authService.logout().catch(() => {});
    clearAuth();
    navigate("/login", { replace: true });
  };

  return {
    user,
    analytics,
    isAnalyticsLoading,
    isAnalyticsError,
    activities,
    isActivitiesLoading,
    isActivitiesError,
    isRefreshing,
    loadAllData,
    fetchAnalytics,
    fetchActivities,
    handleLogout,
  };
}

import React, { useRef, useState } from "react";
import { Upload, X, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";
import { MAX_MEDIA_UPLOAD_SIZE } from "@/lib/constants";

interface MediaDropzoneProps {
  mediaUrls: string[];
  onChange: (urls: string[]) => void;
}

export const MediaDropzone: React.FC<MediaDropzoneProps> = ({
  mediaUrls,
  onChange,
}) => {
  const { t } = useTranslation();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragOver, setIsDragOver] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<number | null>(null);

  const simulateProgress = async (file: File): Promise<string> => {
    return new Promise((resolve) => {
      let progress = 0;
      setUploadProgress(0);

      const interval = setInterval(() => {
        progress += 20;
        setUploadProgress(progress);

        if (progress >= 100) {
          clearInterval(interval);
          setUploadProgress(null);
          const isVideo = file.type.startsWith("video");
          const mockUrl = isVideo
            ? "https://assets.mixkit.co/videos/preview/mixkit-pouring-coffee-into-a-cup-42898-large.mp4"
            : URL.createObjectURL(file);
          resolve(mockUrl);
        }
      }, 150);
    });
  };

  const handleFiles = async (files: FileList | File[]) => {
    const fileArray = Array.from(files);
    if (fileArray.length === 0) return;

    for (const file of fileArray) {
      if (file.size > MAX_MEDIA_UPLOAD_SIZE) {
        toast.error(
          t("editor.mediaDropzone.sizeExceededError", {
            fileName: file.name,
          }),
        );
        continue;
      }

      try {
        const uploadedUrl = await simulateProgress(file);
        onChange([...mediaUrls, uploadedUrl]);
        toast.success(
          t("editor.mediaDropzone.uploadSuccess", { fileName: file.name }),
        );
      } catch (err) {
        toast.error(
          t("editor.mediaDropzone.uploadError", { fileName: file.name }),
        );
      }
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    if (e.dataTransfer.files) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const handleRemoveMedia = (index: number) => {
    const next = [...mediaUrls];
    next.splice(index, 1);
    onChange(next);
  };

  return (
    <div className="space-y-3">
      <input
        type="file"
        ref={fileInputRef}
        onChange={(e) => e.target.files && handleFiles(e.target.files)}
        accept="image/*,video/*"
        multiple
        className="hidden"
      />

      {/* Drag & Drop Box */}
      <div
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragOver(true);
        }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        className={`cursor-pointer rounded-xl border-2 border-dashed p-6 text-center transition-all ${
          isDragOver
            ? "border-brand-orange bg-brand-orange/10 dark:bg-brand-orange/20"
            : "border-border hover:border-brand-orange bg-muted/50"
        }`}
      >
        {uploadProgress !== null ? (
          <div className="mx-auto max-w-xs space-y-3 py-2">
            <div className="text-muted-foreground flex items-center justify-between text-xs font-semibold">
              <span className="flex items-center gap-1.5">
                <Loader2 className="text-brand-orange size-4 animate-spin" />
                {t("editor.mediaDropzone.uploading")}
              </span>
              <span className="font-mono">{uploadProgress}%</span>
            </div>
            <div className="bg-muted h-2 w-full overflow-hidden rounded-full">
              <div
                className="bg-brand-orange h-full rounded-full transition-all duration-150"
                style={{ width: `${uploadProgress}%` }}
              />
            </div>
          </div>
        ) : (
          <div className="space-y-2">
            <div className="bg-brand-orange-soft dark:bg-brand-orange/20 text-brand-orange dark:text-brand-orange/80 mx-auto flex size-10 items-center justify-center rounded-full shadow-xs">
              <Upload className="size-5" />
            </div>
            <h4 className="text-foreground text-xs font-semibold">
              {t("editor.mediaDropzone.dragDropText")}{" "}
              <span className="text-brand-orange dark:text-brand-orange/80">
                {t("editor.mediaDropzone.browseText")}
              </span>
            </h4>
            <p className="text-2xs text-muted-foreground">
              {t("editor.mediaDropzone.supportedFormats")}
            </p>
          </div>
        )}
      </div>

      {/* Uploaded Media Previews */}
      {mediaUrls.length > 0 && (
        <div className="grid grid-cols-3 gap-3 pt-1 sm:grid-cols-4">
          {mediaUrls.map((url, idx) => {
            const isVideo = url.endsWith(".mp4") || url.includes("mixkit");
            return (
              <div
                key={idx}
                className="group border-border relative aspect-square overflow-hidden rounded-xl border bg-zinc-900 shadow-2xs"
              >
                {isVideo ? (
                  <video src={url} className="h-full w-full object-cover" />
                ) : (
                  <img
                    src={url}
                    alt={`Media ${idx}`}
                    className="h-full w-full object-cover"
                  />
                )}

                <button
                  type="button"
                  onClick={() => handleRemoveMedia(idx)}
                  className="absolute top-1.5 right-1.5 rounded-full bg-black/60 p-1 text-white transition-colors hover:bg-red-600"
                >
                  <X className="size-3.5" />
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { LayoutTemplate, Search, Check, X } from "lucide-react";
import { mockTemplateService } from "@/services/mock/mockTemplateService";
import type { ContentTemplate } from "@/types/template";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";
import { Input } from "@/components/ui/input";

interface TemplatePickerModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectTemplate: (template: ContentTemplate) => void;
}

export const TemplatePickerModal: React.FC<TemplatePickerModalProps> = ({
  isOpen,
  onClose,
  onSelectTemplate,
}) => {
  const { t } = useTranslation();
  const [templates, setTemplates] = useState<ContentTemplate[]>([]);
  const [search, setSearch] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setIsLoading(true);
      mockTemplateService
        .getTemplates({ search, page: 0, size: 20 })
        .then((res) => setTemplates(res.items))
        .catch(console.error)
        .finally(() => setIsLoading(false));
    }
  }, [isOpen, search]);

  if (!isOpen) return null;

  const handleApply = (tpl: ContentTemplate) => {
    onSelectTemplate(tpl);
    toast.success(
      t("editor.templatePicker.applySuccess", { title: tpl.title }),
    );
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-xs">
      <div className="animate-in fade-in zoom-in-95 border-border bg-card flex max-h-[85vh] w-full max-w-3xl flex-col overflow-hidden rounded-xl border shadow-2xl duration-200">
        {/* Header */}
        <div className="border-border flex items-center justify-between border-b p-4">
          <div className="flex items-center gap-2">
            <div className="bg-brand-orange-soft text-brand-orange rounded-lg p-1.5">
              <LayoutTemplate className="size-5" />
            </div>
            <div>
              <h3 className="text-foreground text-base font-semibold">
                {t("editor.templatePicker.title")}
              </h3>
              <p className="text-muted-foreground text-xs">
                {t("editor.templatePicker.subtitle")}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-foreground cursor-pointer p-1 text-lg leading-none"
          >
            <X className="size-5" />
          </button>
        </div>

        {/* Search Bar */}
        <div className="border-border bg-muted/50 border-b p-4">
          <div className="relative">
            <Search className="text-muted-foreground absolute top-1/2 left-3 size-4 -translate-y-1/2" />
            <Input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t("editor.templatePicker.searchPlaceholder")}
              className="border-border bg-card text-foreground rounded-xl pr-4 pl-9 text-xs"
            />
          </div>
        </div>

        {/* Template Grid Body */}
        <div className="grid flex-1 grid-cols-1 gap-4 overflow-y-auto p-4 md:grid-cols-2">
          {isLoading ? (
            <div className="text-muted-foreground col-span-2 py-12 text-center text-xs">
              {t("editor.templatePicker.loading")}
            </div>
          ) : templates.length === 0 ? (
            <div className="text-muted-foreground col-span-2 py-12 text-center text-xs">
              {t("editor.templatePicker.empty")}
            </div>
          ) : (
            templates.map((tpl) => (
              <div
                key={tpl.id}
                className="hover:border-brand-orange/50 group border-border bg-card flex flex-col justify-between space-y-3 rounded-xl border p-4 shadow-2xs transition-all"
              >
                <div className="space-y-2">
                  <div className="flex items-center justify-between gap-2">
                    <h4 className="group-hover:text-brand-orange text-foreground line-clamp-1 text-xs font-semibold transition-colors">
                      {tpl.title}
                    </h4>
                    <span className="bg-brand-orange-soft text-brand-orange text-3xs shrink-0 rounded-full px-2 py-0.5 font-mono font-bold">
                      {t("editor.templatePicker.templateBadge")}
                    </span>
                  </div>

                  <p className="text-muted-foreground line-clamp-3 text-xs leading-relaxed">
                    {tpl.caption}
                  </p>
                </div>

                {/* Hashtags & Action */}
                <div className="border-border flex items-center justify-between gap-2 border-t pt-2">
                  <div className="flex max-h-6 flex-wrap gap-1 overflow-hidden">
                    {tpl.hashtags.slice(0, 3).map((tag) => (
                      <span
                        key={tag}
                        className="text-3xs bg-muted text-muted-foreground rounded-xl px-1.5 py-0.5 font-mono"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>

                  <button
                    type="button"
                    onClick={() => handleApply(tpl)}
                    className="bg-brand-orange hover:bg-brand-orange/90 flex shrink-0 cursor-pointer items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-semibold text-white shadow-2xs transition-colors"
                  >
                    <Check className="size-3.5" />
                    <span>{t("editor.templatePicker.apply")}</span>
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

