import React, { useEffect, useState } from "react";
import type { HashtagGroup } from "@/types/contentLibrary";
import { mockContentLibraryService } from "@/services/mock/mockContentLibraryService";
import { Hash, Copy, Plus, Edit2, Trash2, Check, X, Tag } from "lucide-react";
import { toast } from "sonner";
import { COPY_FEEDBACK_DURATION_MS } from "@/lib/constants";
import { useTranslation } from "react-i18next";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

export const HashtagGroupsTab: React.FC = () => {
  const { t } = useTranslation();
  const [groups, setGroups] = useState<HashtagGroup[]>([]);
  const [loading, setLoading] = useState(true);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingGroup, setEditingGroup] = useState<HashtagGroup | null>(null);
  const [groupName, setGroupName] = useState("");
  const [tagsInput, setTagsInput] = useState("");
  const [isSaving, setIsSaving] = useState(false);

  const fetchGroups = async () => {
    setLoading(true);
    try {
      const data = await mockContentLibraryService.getHashtagGroups();
      setGroups(data);
    } catch (err) {
      toast.error(t("hashtagGroups.loadError"));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchGroups();
  }, []);

  const handleCopyGroup = (group: HashtagGroup) => {
    const textToCopy = group.tags.join(" ");
    navigator.clipboard.writeText(textToCopy);
    setCopiedId(group.id);
    toast.success(t("hashtagGroups.copySuccess", { name: group.name }));
    setTimeout(() => setCopiedId(null), COPY_FEEDBACK_DURATION_MS);
  };

  const handleOpenModal = (group?: HashtagGroup) => {
    if (group) {
      setEditingGroup(group);
      setGroupName(group.name);
      setTagsInput(group.tags.join(" "));
    } else {
      setEditingGroup(null);
      setGroupName("");
      setTagsInput("");
    }
    setIsModalOpen(true);
  };

  const handleSaveGroup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!groupName.trim() || !tagsInput.trim()) {
      toast.error(t("hashtagGroups.validationError"));
      return;
    }

    const tagsArray = tagsInput
      .split(/[\s,]+/)
      .map((t) => t.trim())
      .filter((t) => t.length > 0);

    setIsSaving(true);
    try {
      if (editingGroup) {
        const updated = await mockContentLibraryService.updateHashtagGroup(
          editingGroup.id,
          groupName,
          tagsArray,
        );
        setGroups((prev) =>
          prev.map((g) => (g.id === updated.id ? updated : g)),
        );
        toast.success(t("hashtagGroups.updateSuccess"));
      } else {
        const created = await mockContentLibraryService.createHashtagGroup(
          groupName,
          tagsArray,
        );
        setGroups((prev) => [created, ...prev]);
        toast.success(t("hashtagGroups.createSuccess"));
      }
      setIsModalOpen(false);
    } catch (err) {
      toast.error(t("hashtagGroups.saveError"));
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteGroup = async (id: string, name: string) => {
    if (window.confirm(t("hashtagGroups.deleteConfirm", { name }))) {
      try {
        await mockContentLibraryService.deleteHashtagGroup(id);
        setGroups((prev) => prev.filter((g) => g.id !== id));
        toast.success(t("hashtagGroups.deleteSuccess"));
      } catch (err) {
        toast.error(t("hashtagGroups.deleteError"));
      }
    }
  };

  return (
    <div className="space-y-6">
      {/* Header & Add Button */}
      <div className="border-border bg-card flex items-center justify-between rounded-xl border p-4 shadow-xs">
        <div>
          <h3 className="text-foreground flex items-center gap-2 text-sm font-semibold">
            <Hash className="text-brand-orange size-4" />
            {t("hashtagGroups.headerCount", { count: groups.length })}
          </h3>
          <p className="text-muted-foreground text-xs">
            {t("hashtagGroups.headerDescription")}
          </p>
        </div>

        <button
          onClick={() => handleOpenModal()}
          className="bg-brand-orange hover:bg-brand-orange/90 active:bg-brand-orange/80 flex cursor-pointer items-center gap-1.5 rounded-xl px-4 py-2 text-xs font-semibold text-white shadow-xs transition-colors"
        >
          <Plus className="size-4" />
          <span>{t("hashtagGroups.createButton")}</span>
        </button>
      </div>

      {/* Grid List */}
      {loading ? (
        <div className="text-muted-foreground py-12 text-center text-xs">
          {t("hashtagGroups.loading")}
        </div>
      ) : groups.length === 0 ? (
        <div className="border-border bg-card rounded-xl border border-dashed p-8 py-12 text-center">
          <Hash className="text-muted-foreground mx-auto mb-2 size-10" />
          <p className="text-muted-foreground text-xs">
            {t("hashtagGroups.emptyState")}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
          {groups.map((group) => (
            <div
              key={group.id}
              className="hover:border-brand-orange/40 border-border bg-card group flex flex-col justify-between rounded-xl border p-5 shadow-xs transition-all"
            >
              <div>
                <div className="mb-3 flex items-center justify-between">
                  <h4 className="group-hover:text-brand-orange text-foreground flex items-center gap-1.5 text-sm font-semibold transition-colors">
                    <Tag className="text-brand-orange size-3.5" />
                    {group.name}
                  </h4>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => handleOpenModal(group)}
                      className="hover:text-brand-orange text-muted-foreground hover:bg-muted cursor-pointer rounded-lg p-1 transition-colors"
                      title={t("hashtagGroups.editTooltip")}
                    >
                      <Edit2 className="size-3.5" />
                    </button>
                    <button
                      onClick={() => handleDeleteGroup(group.id, group.name)}
                      className="text-muted-foreground cursor-pointer rounded-lg p-1 transition-colors hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-950/40"
                      title={t("hashtagGroups.deleteTooltip")}
                    >
                      <Trash2 className="size-3.5" />
                    </button>
                  </div>
                </div>

                {/* Hashtag List Badges */}
                <div className="mb-4 flex max-h-32 flex-wrap gap-1.5 overflow-y-auto">
                  {group.tags.map((tag, idx) => (
                    <span
                      key={idx}
                      className="bg-brand-orange-soft text-brand-orange border-brand-orange/10 rounded-lg border px-2.5 py-1 font-mono text-xs font-semibold"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* Copy Action Footer */}
              <div className="border-border flex items-center justify-between border-t pt-3">
                <span className="text-2xs text-muted-foreground font-mono">
                  {t("hashtagGroups.hashtagsCount", {
                    count: group.tags.length,
                  })}
                </span>
                <button
                  onClick={() => handleCopyGroup(group)}
                  className="hover:bg-brand-orange dark:hover:bg-brand-orange bg-muted text-foreground flex cursor-pointer items-center gap-1.5 rounded-xl px-3 py-1.5 text-xs font-semibold transition-colors hover:text-white"
                >
                  {copiedId === group.id ? (
                    <>
                      <Check className="size-3.5 text-emerald-500" />
                      <span>{t("hashtagGroups.copied")}</span>
                    </>
                  ) : (
                    <>
                      <Copy className="size-3.5" />
                      <span>{t("hashtagGroups.copyGroupButton")}</span>
                    </>
                  )}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Modal Form Create / Edit */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-xs">
          <div className="border-border bg-card w-full max-w-md space-y-4 rounded-xl border p-6 shadow-2xl">
            <div className="border-border flex items-center justify-between border-b pb-3">
              <h3 className="text-foreground text-sm font-semibold">
                {editingGroup
                  ? t("hashtagGroups.editModalTitle")
                  : t("hashtagGroups.createModalTitle")}
              </h3>
              <button
                onClick={() => setIsModalOpen(false)}
                className="text-muted-foreground hover:text-foreground cursor-pointer"
              >
                <X className="size-5" />
              </button>
            </div>

            <form onSubmit={handleSaveGroup} className="space-y-4">
              <div>
                <label className="text-foreground mb-1 block text-xs font-semibold">
                  {t("hashtagGroups.nameFieldLabel")}
                </label>
                <Input
                  type="text"
                  value={groupName}
                  onChange={(e) => setGroupName(e.target.value)}
                  placeholder={t("hashtagGroups.namePlaceholder")}
                  className="border-border bg-muted text-foreground rounded-xl text-xs"
                />
              </div>

              <div>
                <label className="text-foreground mb-1 block text-xs font-semibold">
                  {t("hashtagGroups.tagsFieldLabel")}
                </label>
                <Textarea
                  rows={4}
                  value={tagsInput}
                  onChange={(e) => setTagsInput(e.target.value)}
                  placeholder={t("hashtagGroups.tagsPlaceholder")}
                  className="border-border bg-muted text-foreground rounded-xl font-mono text-xs"
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="border-border text-foreground cursor-pointer rounded-xl border px-4 py-2 text-xs font-medium"
                >
                  {t("hashtagGroups.cancelButton")}
                </button>
                <button
                  type="submit"
                  disabled={isSaving}
                  className="bg-brand-orange hover:bg-brand-orange/90 cursor-pointer rounded-xl px-4 py-2 text-xs font-semibold text-white disabled:opacity-50"
                >
                  {isSaving
                    ? t("hashtagGroups.saving")
                    : t("hashtagGroups.saveButton")}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from "react";
import type { MediaItem } from "@/types/contentLibrary";
import {
  X,
  Copy,
  Trash2,
  Calendar,
  HardDrive,
  Maximize2,
  Film,
  Image as ImageIcon,
  Check,
} from "lucide-react";
import { toast } from "sonner";
import { COPY_FEEDBACK_DURATION_MS } from "@/lib/constants";
import { formatFileSize } from "@/lib/utils";
import { useTranslation } from "react-i18next";

interface MediaDetailPanelProps {
  media: MediaItem | null;
  onClose: () => void;
  onDelete: (id: string) => Promise<void>;
}

export const MediaDetailPanel: React.FC<MediaDetailPanelProps> = ({
  media,
  onClose,
  onDelete,
}) => {
  const { t } = useTranslation();
  const [copied, setCopied] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  if (!media) return null;

  const handleCopyUrl = () => {
    navigator.clipboard.writeText(media.url);
    setCopied(true);
    toast.success(t("library.media.copyUrlSuccess"));
    setTimeout(() => setCopied(false), COPY_FEEDBACK_DURATION_MS);
  };

  const handleDelete = async () => {
    if (
      window.confirm(
        t("library.media.deleteConfirm", { filename: media.filename }),
      )
    ) {
      setIsDeleting(true);
      try {
        await onDelete(media.id);
        toast.success(t("library.media.deleteFileSuccess"));
        onClose();
      } catch (err) {
        toast.error(t("library.media.deleteError"));
      } finally {
        setIsDeleting(false);
      }
    }
  };

  const formatDate = (isoString: string) => {
    const d = new Date(isoString);
    return d.toLocaleDateString("vi-VN", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end overflow-hidden bg-black/40 backdrop-blur-xs transition-opacity">
      <div className="bg-card border-border flex h-full w-full max-w-md transform flex-col border-l shadow-2xl transition-transform">
        {/* Header */}
        <div className="border-border flex items-center justify-between border-b p-4">
          <h3 className="text-foreground flex items-center gap-2 text-sm font-semibold">
            {media.type === "video" ? (
              <Film className="text-brand-orange size-4" />
            ) : (
              <ImageIcon className="text-brand-orange size-4" />
            )}
            {t("library.media.detailTitle")}
          </h3>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:bg-muted hover:text-foreground cursor-pointer rounded-lg p-1 transition-colors"
          >
            <X className="size-5" />
          </button>
        </div>

        {/* Content Body */}
        <div className="flex-1 space-y-6 overflow-y-auto p-5">
          {/* Media Preview Box */}
          <div className="border-border group relative flex min-h-[220px] items-center justify-center overflow-hidden rounded-xl border bg-zinc-950">
            {media.type === "video" ? (
              <video
                src={media.url}
                controls
                className="max-h-[300px] w-full object-contain"
                poster={media.thumbnailUrl}
              />
            ) : (
              <img
                src={media.url}
                alt={media.filename}
                className="max-h-[300px] w-full object-contain"
              />
            )}
          </div>

          {/* Title & Badge */}
          <div>
            <span className="bg-brand-orange-soft text-brand-orange mb-2 inline-block rounded-full px-2.5 py-1 text-xs font-bold tracking-wide uppercase">
              {media.type}
            </span>
            <h4 className="text-foreground text-base leading-snug font-medium break-all">
              {media.filename}
            </h4>
          </div>

          {/* Metadata Grid */}
          <div className="bg-muted/50 border-border text-muted-foreground space-y-3 rounded-xl border p-4 text-sm">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground flex items-center gap-2 text-xs">
                <HardDrive className="size-4" /> {t("library.media.sizeLabel")}
              </span>
              <span className="text-foreground font-mono font-medium">
                {formatFileSize(media.sizeBytes)}
              </span>
            </div>

            {media.width && media.height && (
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground flex items-center gap-2 text-xs">
                  <Maximize2 className="size-4" />{" "}
                  {t("library.media.resolutionLabel")}
                </span>
                <span className="text-foreground font-mono font-medium">
                  {media.width} × {media.height} px
                </span>
              </div>
            )}

            {media.durationSeconds && (
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground flex items-center gap-2 text-xs">
                  <Film className="size-4" /> {t("library.media.durationLabel")}
                </span>
                <span className="text-foreground font-mono font-medium">
                  {t("library.media.durationSeconds", {
                    seconds: media.durationSeconds,
                  })}
                </span>
              </div>
            )}

            <div className="flex items-center justify-between">
              <span className="text-muted-foreground flex items-center gap-2 text-xs">
                <Calendar className="size-4" />{" "}
                {t("library.media.uploadedAtLabel")}
              </span>
              <span className="text-foreground text-xs">
                {formatDate(media.createdAt)}
              </span>
            </div>
          </div>

          {/* S3 Direct Link Input Box */}
          <div className="space-y-1.5">
            <label className="text-muted-foreground text-xs font-semibold">
              {t("library.media.directUrlLabel")}
            </label>
            <div className="flex gap-2">
              <input
                type="text"
                readOnly
                value={media.url}
                className="bg-muted border-border text-muted-foreground flex-1 rounded-lg border px-3 py-2 font-mono text-xs focus:outline-hidden"
              />
              <button
                onClick={handleCopyUrl}
                className="bg-brand-orange hover:bg-brand-orange/90 flex shrink-0 cursor-pointer items-center gap-1.5 rounded-lg px-3 py-2 text-xs font-semibold text-white shadow-xs transition-colors"
              >
                {copied ? (
                  <Check className="size-4" />
                ) : (
                  <Copy className="size-4" />
                )}
                {copied ? t("library.media.copied") : t("library.media.copy")}
              </button>
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="border-border bg-muted flex items-center justify-between border-t p-4">
          <button
            onClick={handleDelete}
            disabled={isDeleting}
            className="flex cursor-pointer items-center gap-1.5 rounded-xl bg-red-50 px-4 py-2 text-xs font-semibold text-red-600 transition-colors hover:bg-red-100 dark:bg-red-950/40 dark:text-red-400 dark:hover:bg-red-900/60"
          >
            <Trash2 className="size-4" />
            {isDeleting
              ? t("library.media.deleting")
              : t("library.media.deleteFileButton")}
          </button>

          <button
            onClick={onClose}
            className="border-border text-foreground hover:bg-muted cursor-pointer rounded-xl border px-4 py-2 text-xs font-medium transition-colors"
          >
            {t("library.media.close")}
          </button>
        </div>
      </div>
    </div>
  );
};

