import React, { useState, useEffect } from "react";
import { X, FileEdit } from "lucide-react";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";
import type {
  ContentRequest,
  ReviseContentRequestPayload,
  SocialPlatform,
} from "@/types/contentRequest";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

const PLATFORMS: SocialPlatform[] = [
  "FACEBOOK",
  "INSTAGRAM",
  "TIKTOK",
  "THREADS",
  "YOUTUBE",
];

interface ReviseRequestModalProps {
  request: ContentRequest | null;
  onClose: () => void;
  onConfirm: (
    requestId: string,
    payload: ReviseContentRequestPayload,
  ) => Promise<void>;
}

export const ReviseRequestModal: React.FC<ReviseRequestModalProps> = ({
  request,
  onClose,
  onConfirm,
}) => {
  const { t } = useTranslation();
  const [topic, setTopic] = useState("");
  const [deadline, setDeadline] = useState("");
  const [platforms, setPlatforms] = useState<SocialPlatform[]>([]);
  const [briefNote, setBriefNote] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (request) {
      setTopic(request.topic);
      setDeadline(request.deadline);
      setPlatforms(request.platforms);
      setBriefNote(request.briefNote ?? "");
    }
  }, [request]);

  if (!request) return null;

  const togglePlatform = (p: SocialPlatform) => {
    setPlatforms((prev) =>
      prev.includes(p) ? prev.filter((x) => x !== p) : [...prev, p],
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim() || !deadline || platforms.length === 0) {
      toast.error(t("requests.create.validationError"));
      return;
    }

    setIsSubmitting(true);
    try {
      await onConfirm(request.id, {
        topic: topic.trim(),
        deadline,
        platforms,
        briefNote: briefNote.trim() || undefined,
      });
      onClose();
    } catch (err) {
      toast.error(t("requests.revise.error"));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 backdrop-blur-xs">
      <div className="bg-card border-border max-h-[90vh] w-full max-w-lg space-y-4 overflow-y-auto rounded-xl border p-6 shadow-2xl">
        <div className="border-border flex items-center justify-between border-b pb-3">
          <div className="flex items-center gap-2">
            <FileEdit className="text-brand-orange dark:text-brand-orange/80 size-5" />
            <h3 className="text-foreground text-sm font-semibold">
              {t("requests.revise.title")}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-foreground rounded-lg p-1"
          >
            <X className="size-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col gap-1.5">
            <label className="text-foreground text-xs font-semibold">
              {t("requests.create.topicLabel")}
            </label>
            <Input
              type="text"
              value={topic}
              onChange={(e) => setTopic(e.target.value)}
              className="bg-muted text-foreground focus:ring-brand-orange/20 border-border h-auto w-full rounded-xl border px-3 py-2 text-xs focus:ring-2 focus:outline-hidden"
              required
            />
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-foreground text-xs font-semibold">
              {t("requests.create.deadlineLabel")}
            </label>
            <Input
              type="date"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              className="bg-muted text-foreground focus:ring-brand-orange/20 border-border h-auto w-full rounded-xl border px-3 py-2 text-xs focus:ring-2 focus:outline-hidden"
              required
            />
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-foreground text-xs font-semibold">
              {t("requests.create.platformsLabel")}
            </label>
            <div className="flex flex-wrap gap-2">
              {PLATFORMS.map((p) => {
                const active = platforms.includes(p);
                return (
                  <button
                    key={p}
                    type="button"
                    onClick={() => togglePlatform(p)}
                    className={`rounded-xl border px-3 py-1.5 text-xs font-medium transition-colors ${
                      active
                        ? "border-brand-orange bg-brand-orange-soft text-brand-orange"
                        : "border-border text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {p}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex flex-col gap-1.5">
            <label className="text-foreground text-xs font-semibold">
              {t("requests.create.briefLabel")}
            </label>
            <Textarea
              value={briefNote}
              onChange={(e) => setBriefNote(e.target.value)}
              rows={3}
              className="bg-muted text-foreground focus:ring-brand-orange/20 border-border min-h-0 w-full resize-none rounded-xl border px-3 py-2 text-xs focus:ring-2 focus:outline-hidden"
            />
          </div>

          <div className="border-border flex justify-end gap-2 border-t pt-3">
            <Button
              variant="outline"
              type="button"
              onClick={onClose}
              className="border-border text-muted-foreground h-auto rounded-xl border px-4 py-2 text-xs font-medium"
            >
              {t("requests.create.cancel")}
            </Button>
            <Button
              variant="orange"
              type="submit"
              disabled={isSubmitting}
              className="bg-brand-orange hover:bg-brand-orange/90 h-auto cursor-pointer px-4 py-2 text-xs font-medium text-white"
            >
              {isSubmitting
                ? t("requests.revise.submitting")
                : t("requests.revise.submit")}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

