import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { useTranslation } from "react-i18next";
import { mockTemplateService } from "@/services/mock/mockTemplateService";
import type { ContentTemplate } from "@/types/template";

export function useTemplates() {
  const { t } = useTranslation();
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [page, setPage] = useState(0);
  const [templates, setTemplates] = useState<ContentTemplate[]>([]);
  const [total, setTotal] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedTemplate, setSelectedTemplate] =
    useState<ContentTemplate | null>(null);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(0);
    }, 300);

    return () => clearTimeout(handler);
  }, [searchTerm]);

  const fetchTemplates = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await mockTemplateService.getTemplates({
        search: debouncedSearch,
        page,
        size: 20,
      });
      setTemplates(res.items);
      setTotal(res.total);
      setTotalPages(res.totalPages);
    } catch (err) {
      toast.error(t("templates.toast.loadError"));
    } finally {
      setIsLoading(false);
    }
  }, [debouncedSearch, page]);

  useEffect(() => {
    fetchTemplates();
  }, [fetchTemplates]);

  const handleOpenPreview = (template: ContentTemplate) => {
    setSelectedTemplate(template);
    setIsPreviewOpen(true);
  };

  const handleDeleteTemplate = async (id: string, title: string) => {
    if (window.confirm(t("templates.toast.deleteConfirm", { title }))) {
      try {
        await mockTemplateService.deleteTemplate(id);
        toast.success(t("templates.toast.deleteSuccess", { title }));
        fetchTemplates();
      } catch (err) {
        toast.error(t("templates.toast.deleteError"));
      }
    }
  };

  return {
    searchTerm,
    setSearchTerm,
    page,
    setPage,
    templates,
    total,
    totalPages,
    isLoading,
    selectedTemplate,
    isPreviewOpen,
    setIsPreviewOpen,
    handleOpenPreview,
    handleDeleteTemplate,
  };
}

import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Select } from "@/components/ui/select";
import { clientProfileService } from "@/services/clientProfileService";
import type { ClientProfile } from "@/types/clientProfile";
import type { WorkspaceMember } from "@/types/workspace";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  agencyId: string;
  existingMembers: WorkspaceMember[];
  value: string;
  onChange: (clientProfileId: string) => void;
  submitting: boolean;
  onSubmit: () => void;
}

// Gán 1 ClientProfile (đã có sẵn trong agency, không thuộc agency_members)
// vào workspace hiện tại với role CLIENT — thành viên cộng tác, không phải
// agency member.
export function AddClientDialog({
  open,
  onOpenChange,
  agencyId,
  existingMembers,
  value,
  onChange,
  submitting,
  onSubmit,
}: Props) {
  const { t } = useTranslation();
  const [clients, setClients] = useState<ClientProfile[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    clientProfileService
      .listByAgency(agencyId)
      .then(({ data }) => setClients(data.data))
      .catch(() => setClients([]))
      .finally(() => setLoading(false));
  }, [open, agencyId]);

  const existingClientIds = new Set(
    existingMembers
      .filter((m) => m.role === "CLIENT" && m.clientProfileId)
      .map((m) => m.clientProfileId),
  );
  const available = clients.filter((c) => !existingClientIds.has(c.id));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("workspace.members.addClientTitle")}</DialogTitle>
        </DialogHeader>

        {!loading && available.length === 0 ? (
          <p className="text-muted-foreground text-sm">
            {t("workspace.members.addClientEmpty")}
          </p>
        ) : (
          <Select value={value} onChange={(e) => onChange(e.target.value)}>
            <option value="">
              {t("workspace.members.addClientPlaceholder")}
            </option>
            {available.map((c) => (
              <option key={c.id} value={c.id}>
                {c.displayName}
                {c.company ? ` — ${c.company}` : ""}
              </option>
            ))}
          </Select>
        )}

        <DialogFooter>
          <Button
            variant="orange"
            loading={submitting}
            onClick={onSubmit}
            disabled={!value}
          >
            {t("workspace.members.addClientSubmit")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import type {
  PostDraft,
  AIGenerateRequest,
  AIGenerateResponse,
} from "@/types/editor";

const MOCK_AI_IMAGES = [
  "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=1000&q=80",
  "https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=1000&q=80",
  "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=1000&q=80",
  "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1000&q=80",
];

class MockEditorService {
  private draft: PostDraft = {
    id: "post-99",
    title: "Nike Air Max Pulse — Mở bán đợt 1",
    caption:
      "Đột phá phong cách với dòng Nike Air Max Pulse hoàn toàn mới! Với đệm khí Air cải tiến mang lại độ đàn hồi vượt trội.",
    hashtags: ["#NikeAirMax", "#AirMaxPulse", "#Sneakerhead", "#BrandHub"],
    mediaUrls: [
      "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=1000&q=80",
    ],
    targetPlatforms: ["FACEBOOK", "INSTAGRAM", "TIKTOK"],
    status: "DRAFT",
    updatedAt: new Date().toISOString(),
  };

  private async delay(ms: number = 300) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async getDraft(_id?: string): Promise<PostDraft> {
    await this.delay(200);
    return { ...this.draft };
  }

  async autoSaveDraft(
    _id: string,
    payload: Partial<PostDraft>,
  ): Promise<{ success: boolean; updatedAt: string }> {
    await this.delay(300);
    this.draft = {
      ...this.draft,
      ...payload,
      updatedAt: new Date().toISOString(),
    };
    return { success: true, updatedAt: this.draft.updatedAt };
  }

  async submitForReview(
    _id: string,
  ): Promise<{ success: boolean; status: string }> {
    await this.delay(500);
    this.draft.status = "PENDING_REVIEW";
    return { success: true, status: "PENDING_REVIEW" };
  }

  async generateWithAI(
    req: AIGenerateRequest,
    onChunk?: (partial: string) => void,
  ): Promise<AIGenerateResponse> {
    // Simulate error testing if prompt contains "error" or "fail"
    if (req.prompt.toLowerCase().includes("error")) {
      await this.delay(1000);
      throw new Error("SERVICE_UNAVAILABLE");
    }
    if (req.prompt.toLowerCase().includes("limit")) {
      await this.delay(1000);
      throw new Error("RATE_LIMITED");
    }

    const isHàiHước =
      req.prompt.toLowerCase().includes("hài") ||
      req.prompt.toLowerCase().includes("funny");
    const isFeedback = !!req.userFeedback;

    const result = this.buildContentByType(req, isHàiHước);

    if (isFeedback) {
      result.caption = `[Đã tối ưu theo phản hồi: "${req.userFeedback}"]\n\n${result.caption}`;
    }

    const allHashtags = [
      "#BrandHub",
      "#Fashion2026",
      "#StreetStyle",
      "#TrendingNow",
      "#MustHave",
      "#StabilityAI",
    ];
    const hashtags =
      req.contentType === "CAPTION"
        ? allHashtags.slice(0, req.hashtagCount ?? allHashtags.length)
        : allHashtags.slice(0, 3);
    const randomImage =
      MOCK_AI_IMAGES[Math.floor(Math.random() * MOCK_AI_IMAGES.length)];

    // Stream chunks simulation if callback provided
    if (onChunk) {
      const words = result.caption.split(" ");
      let current = "";
      for (let i = 0; i < words.length; i++) {
        current += (i === 0 ? "" : " ") + words[i];
        onChunk(current);
        await this.delay(40);
      }
    } else {
      await this.delay(1500);
    }

    return {
      ...result,
      hashtags,
      imageUrl: req.contentType === "CAPTION" ? randomImage : undefined,
      reasoning:
        "Gợi ý nội dung và hình ảnh nghệ thuật Stability AI được tối ưu hóa theo phong cách của bạn.",
    };
  }

  private buildContentByType(
    req: AIGenerateRequest,
    isHàiHước: boolean,
  ): {
    caption: string;
    blogTitle?: string;
    adHeadline?: string;
    adDescription?: string;
  } {
    if (req.contentType === "BLOG") {
      const keyword = req.blogKeyword?.trim() || "Air Max Pulse";
      const intro = `Mở bài: Thị trường sneaker đầu năm 2026 chứng kiến sự trở lại mạnh mẽ của dòng đệm khí Air với phiên bản ${keyword} hoàn toàn mới.`;
